function ManualTestsPanel({moduleKey, moduleLabel, tests}) { // VL-MANUAL-REDESIGN-V3
  const STORAGE_PREFIX = `vl_manual:${moduleKey}:`;
  const ONB_KEY = `vl_onb:${moduleKey}`;
  const [findings, setFindings] = React.useState(() => {
    const out = {};
    (tests || []).forEach(t => {
      try { const raw = localStorage.getItem(STORAGE_PREFIX + t.id); if (raw) out[t.id] = JSON.parse(raw); } catch(_){}
    });
    return out;
  });
  const [expanded, setExpanded] = React.useState({});
  const [search, setSearch] = React.useState("");
  const [statusFilter, setStatusFilter] = React.useState("all");
  const [saveFlash, setSaveFlash] = React.useState({});
  const [onbDismissed, setOnbDismissed] = React.useState(() => {
    try { return !!localStorage.getItem(ONB_KEY); } catch(_) { return false; }
  });
  const update = (testId, patch) => {
    setFindings(p => {
      const next = {...p, [testId]: {...(p[testId]||{}), ...patch, updated_at: Date.now()}};
      try { localStorage.setItem(STORAGE_PREFIX + testId, JSON.stringify(next[testId])); } catch(_){}
      return next;
    });
    setSaveFlash(p => ({...p, [testId]: Date.now()}));
    setTimeout(() => setSaveFlash(p => { const n={...p}; delete n[testId]; return n; }), 1500);
  };
  const dismissOnb = () => { setOnbDismissed(true); try { localStorage.setItem(ONB_KEY, "1"); } catch(_){} };
  const groups = React.useMemo(() => {
    const g = {};
    (tests||[]).forEach(t => {
      const m = (t.ref||"").match(/§\s*(\d+)/);
      const key = m ? "§" + m[1] : "Other";
      (g[key] = g[key] || []).push(t);
    });
    return g;
  }, [tests]);
  const groupKeys = Object.keys(groups).sort((a,b) => {
    const na = parseInt(a.replace("§",""))||999, nb = parseInt(b.replace("§",""))||999;
    return na - nb;
  });
  const completedCount = Object.values(findings).filter(f => f && f.status && f.status !== "not_run").length;
  const totalCount = (tests || []).length;
  const requiredCount = (tests||[]).filter(t => t.required).length;
  const pct = totalCount ? Math.round(100 * completedCount / totalCount) : 0;
  const SEV_COLORS = {HIGH:"#ff3e5e", MEDIUM:"#f59e0b", LOW:"#00ff88", "no-finding":"#00ff88", na:"#5a6478", not_run:"#5a6478", required:"#fbbf24", all:"#7c3aed"};
  const SECTION_COLORS = {"§1":"#3b9eff","§2":"#06b6d4","§3":"#8b5cf6","§4":"#ec4899","§5":"#f97316","§6":"#84cc16","§7":"#eab308","§8":"#10b981","§9":"#ff3e5e","§10":"#a855f7","§11":"#0ea5e9","§12":"#f472b6","§13":"#facc15","§14":"#fb923c","§15":"#22d3ee"};
  const DIFF_BADGES = {easy:{emoji:"",label:"Easy",color:"#00ff88"},medium:{emoji:"",label:"Med",color:"#f59e0b"},hard:{emoji:"",label:"Hard",color:"#ff3e5e"},expert:{emoji:"",label:"Expert",color:"#5a6478"}};
  const matches = (t) => {
    if (search) {
      const q = search.toLowerCase();
      const hay = (t.title||"") + " " + (t.ref||"") + " " + (t.tools_required||[]).join(",");
      if (!hay.toLowerCase().includes(q)) return false;
    }
    if (statusFilter === "required") { if (!t.required) return false; }
    else if (statusFilter !== "all") {
      const f = findings[t.id] || {};
      const st = f.status === "na" ? "na" : ((f.status === "not_run" || !f.status) ? "not_run" : (f.severity || "no-finding"));
      if (st !== statusFilter) return false;
    }
    return true;
  };
  if (!tests || tests.length === 0) return null;
  return (
    <div style={{background:"#0d1320", border:"1px solid #103a52", borderRadius:10, overflow:"hidden"}}>
      {!onbDismissed && (
        <div style={{background:"linear-gradient(135deg,#172554,#1e1b4b)", borderBottom:"1px solid #103a52", padding:"14px 16px"}}>
          <div style={{display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8}}>
            <div style={{fontSize:13, fontWeight:700, color:"#fbbf24"}}>First time? Here is the 5-step workflow</div>
            <button onClick={dismissOnb} style={{background:"none", border:"none", color:"#8a94a8", cursor:"pointer", fontSize:14, padding:0, lineHeight:1}}></button>
          </div>
          <ol style={{margin:"0 0 8px 0", paddingLeft:18, fontSize:11, color:"#c3ccda", lineHeight:1.7}}>
            <li>Click a card to expand it</li>
            <li>Read <b>What customer needs</b> + <b>Steps</b></li>
            <li>Run the steps locally (or on the target with authorization)</li>
            <li>Paste output in the evidence box, mark severity (OK / Low / Med / High) — or <b>N/A</b> if out of scope</li>
            <li>Click <b>Export PDF</b> when done</li>
          </ol>
          {requiredCount > 0 && (
            <div style={{fontSize:10, color:"#fbbf24", marginTop:6}}>Tip: click <span style={{padding:"1px 6px", border:"1px solid #fbbf24", borderRadius:3, fontWeight:700}}>Required</span> to see the {requiredCount} must-do techniques.</div>
          )}
        </div>
      )}
      <div style={{position:"sticky", top:0, zIndex:5, background:"#0d1320", borderBottom:"1px solid #103a52", padding:"14px 16px"}}>
        <div style={{display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:10, gap:12}}>
          <div style={{minWidth:0}}>
            <div style={{fontSize:14, fontWeight:700, color:"#fbbf24"}}>Manual Tests — {moduleLabel}</div>
            <div style={{fontSize:10, color:"#8a94a8", marginTop:2}}>{totalCount} techniques{requiredCount ? (" · " + requiredCount + " required") : ""} · run locally · paste evidence for the PDF</div>
          </div>
          <button onClick={() => { try { generateManualTestsReport({moduleKey, moduleLabel, tests, findings, date: new Date().toLocaleString()}); } catch(e) { alert("PDF error: " + (e.message || e)); } }} disabled={completedCount === 0} style={{background: completedCount === 0 ? "#374151" : "#7c3aed", border:"none", borderRadius:6, padding:"7px 14px", color:"#fff", fontSize:12, fontWeight:700, cursor: completedCount === 0 ? "not-allowed" : "pointer", opacity: completedCount === 0 ? 0.5 : 1, whiteSpace:"nowrap"}}>Export PDF</button>
        </div>
        <div style={{height:5, background:"#1c2435", borderRadius:3, overflow:"hidden", marginBottom:8}}>
          <div style={{height:"100%", width:`${pct}%`, background: pct === 100 ? "#00ff88" : "#7c3aed", transition:"width 0.3s"}}/>
        </div>
        <div style={{fontSize:10, color:"#8a94a8", marginBottom:10}}><span style={{color: completedCount===totalCount ? "#00ff88" : "#fbbf24", fontWeight:700}}>{completedCount}/{totalCount}</span> covered · {pct}%</div>
        <div style={{display:"flex", gap:6, alignItems:"center", flexWrap:"wrap"}}>
          <input type="text" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search title / ref / tool…" style={{flex:"1 1 160px", minWidth:120, background:"#0a0e17", border:"1px solid #1c2435", borderRadius:6, color:"#c3ccda", fontSize:11, padding:"6px 10px", outline:"none"}}/>
          {[["all","All"],["required","Required"],["not_run","Not Run"],["no-finding","OK"],["LOW","Low"],["MEDIUM","Med"],["HIGH","High"],["na","N/A"]].map(([val,label])=>(
            <button key={val} onClick={()=>setStatusFilter(val)} style={{background: statusFilter===val ? (SEV_COLORS[val] || "#7c3aed") : "transparent", color: statusFilter===val ? "#fff" : (SEV_COLORS[val] || "#8a94a8"), border:`1px solid ${SEV_COLORS[val] || "#5a6478"}`, borderRadius:4, padding:"4px 9px", fontSize:10, fontWeight:700, cursor:"pointer"}}>{label}</button>
          ))}
        </div>
      </div>
      <div style={{padding:"14px 16px"}}>
        {groupKeys.map(gk => {
          const groupTests = groups[gk].filter(matches);
          if (groupTests.length === 0) return null;
          const groupColor = SECTION_COLORS[gk] || "#7c3aed";
          const groupReq = groupTests.filter(t => t.required).length;
          return (
            <div key={gk} style={{marginBottom:18}}>
              <div style={{display:"flex", alignItems:"center", gap:8, marginBottom:8, paddingBottom:6, borderBottom:`1px solid ${groupColor}33`}}>
                <div style={{width:3, height:14, background: groupColor, borderRadius:2}}/>
                <div style={{fontSize:11, fontWeight:700, color: groupColor, textTransform:"uppercase", letterSpacing:0.5}}>{gk}</div>
                <div style={{fontSize:10, color:"#5a6478"}}>{groupTests.length} technique{groupTests.length>1?"s":""}{groupReq ? (" · " + groupReq + " ") : ""}</div>
              </div>
              <div style={{display:"grid", gap:8}}>
                {groupTests.map(t => {
                  const f = findings[t.id] || {};
                  const isOpen = !!expanded[t.id];
                  const status = f.status || "not_run";
                  const sev = f.severity || "no-finding";
                  const isNA = status === "na";
                  const statusColor = isNA ? "#5a6478" : (status === "not_run" ? "#5a6478" : (SEV_COLORS[sev] || "#5a6478"));
                  const flashing = !!saveFlash[t.id];
                  const diff = t.difficulty && DIFF_BADGES[t.difficulty];
                  return (
                    <div key={t.id} style={{background:"#0d1320", border:`1px solid ${isOpen ? groupColor : "#1c2435"}`, borderRadius:8, overflow:"hidden"}}>
                      <div onClick={() => setExpanded(p => ({...p, [t.id]: !p[t.id]}))} style={{display:"flex", alignItems:"center", padding:"10px 14px", cursor:"pointer", gap:10, background: isOpen ? `${groupColor}11` : "transparent"}}>
                        <div style={{width:8, height:8, borderRadius:4, background: statusColor, flexShrink:0}}/>
                        <div style={{flex:1, minWidth:0}}>
                          <div style={{fontSize:13, fontWeight:600, color:"#d8deea", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap"}}>{t.required && <span style={{color:"#fbbf24", marginRight:5}}></span>}{t.title}</div>
                          <div style={{display:"flex", gap:4, flexWrap:"wrap", marginTop:3, alignItems:"center"}}>
                            <span style={{fontSize:9, color:"#5a6478", padding:"1px 5px", border:"1px solid #1c2435", borderRadius:3}}>{t.ref}</span>
                            {diff && (<span style={{fontSize:9, color:diff.color, padding:"1px 5px", background:"#1c2435", borderRadius:3, whiteSpace:"nowrap"}}>{diff.emoji} {diff.label}</span>)}
                            {t.time && (<span style={{fontSize:9, color:"#8a94a8", padding:"1px 5px", background:"#1c2435", borderRadius:3, whiteSpace:"nowrap"}}>{t.time}</span>)}
                            {t.cost && (<span style={{fontSize:9, color: t.cost === "free" ? "#00ff88" : "#f59e0b", padding:"1px 5px", background:"#1c2435", borderRadius:3, whiteSpace:"nowrap"}}>{t.cost === "free" ? "Free" : "Paid"}</span>)}
                            {(t.tools_required||[]).slice(0,2).map((tool,i)=>(<span key={i} style={{fontSize:9, color:"#8a94a8", padding:"1px 5px", background:"#1c2435", borderRadius:3, whiteSpace:"nowrap"}}>{tool}</span>))}
                            {(t.tools_required||[]).length > 2 && (<span style={{fontSize:9, color:"#5a6478"}}>+{(t.tools_required||[]).length-2}</span>)}
                          </div>
                        </div>
                        {status !== "not_run" && (<span style={{background: statusColor, color:"#fff", padding:"2px 8px", borderRadius:4, fontSize:9, fontWeight:700, textTransform:"uppercase", flexShrink:0}}>{isNA ? "N/A" : (sev === "no-finding" ? "OK" : sev)}</span>)}
                        <span style={{color:"#5a6478", fontSize:11, flexShrink:0}}>{isOpen ? "▼" : "▶"}</span>
                      </div>
                      {isOpen && (
                        <div style={{padding:"4px 14px 14px", borderTop:"1px solid #1c2435"}}>
                          <div style={{display:"grid", gridTemplateColumns:"minmax(0,1fr) minmax(0,1fr)", gap:14, marginTop:12}}>
                            <div>
                              <div style={{fontSize:11, fontWeight:700, color:"#fbbf24", marginBottom:6, textTransform:"uppercase", letterSpacing:0.4}}>What customer needs</div>
                              <ul style={{margin:0, paddingLeft:16, fontSize:11, color:"#c3ccda", lineHeight:1.6}}>{(t.customer_prereqs||[]).map((p,i)=><li key={i}>{p}</li>)}</ul>
                              <div style={{fontSize:11, fontWeight:700, color:"#fbbf24", marginTop:12, marginBottom:6, textTransform:"uppercase", letterSpacing:0.4}}>Steps</div>
                              <ol style={{margin:0, paddingLeft:16, fontSize:11, color:"#c3ccda", lineHeight:1.6}}>{(t.steps||[]).map((s,i)=>(<li key={i} style={{marginBottom:4}}>{s.startsWith("$") ? (<code style={{background:"#0a0e17", color:"#5dffa6", padding:"2px 6px", borderRadius:3, fontSize:10, fontFamily:"monospace"}}>{s.slice(1).trim()}</code>) : s}</li>))}</ol>
                            </div>
                            <div>
                              <div style={{fontSize:11, fontWeight:700, color:"#fbbf24", marginBottom:6, textTransform:"uppercase", letterSpacing:0.4}}>What to look for</div>
                              <div style={{fontSize:11, color:"#c3ccda", lineHeight:1.5, marginBottom:12, padding:8, background:"#0a0e17", borderRadius:4, border:"1px solid #1c2435"}}>{t.what_to_look_for}</div>
                              <div style={{display:"flex", alignItems:"center", gap:8, marginBottom:6}}>
                                <div style={{fontSize:11, fontWeight:700, color:"#fbbf24", textTransform:"uppercase", letterSpacing:0.4}}>Your findings</div>
                                {flashing && <span style={{fontSize:9, color:"#00ff88", fontWeight:700}}>saved</span>}
                              </div>
                              <textarea value={f.evidence||""} onChange={e=>update(t.id, {evidence: e.target.value})} placeholder="Paste output / screenshot link / describe what happened…" style={{width:"100%", minHeight:90, background:"#0a0e17", color:"#c3ccda", border:"1px solid #1c2435", borderRadius:4, padding:"6px 8px", fontSize:11, fontFamily:"monospace", resize:"vertical", outline:"none", boxSizing:"border-box"}}/>
                              <div style={{display:"flex", gap:4, marginTop:8, flexWrap:"wrap"}}>
                                {[["not_run","Not Run","#5a6478"],["no-finding","OK","#00ff88"],["LOW","Low","#00ff88"],["MEDIUM","Med","#f59e0b"],["HIGH","High","#ff3e5e"],["na","N/A","#5a6478"]].map(([val,label,c])=>{
                                  const active = (val==="not_run" && status==="not_run") || (val==="na" && status==="na") || (val!=="not_run" && val!=="na" && f.severity===val);
                                  return (<button key={val} onClick={()=>update(t.id, val==="not_run" ? {status:"not_run", severity:undefined} : val==="na" ? {status:"na", severity:undefined} : {status:"done", severity:val})} style={{background: active?c:"transparent", color: active?"#fff":c, border:`1px solid ${c}`, borderRadius:4, padding:"4px 10px", fontSize:10, fontWeight:700, cursor:"pointer"}}>{label}</button>);
                                })}
                              </div>
                              {t.owasp_masvs && (<div style={{marginTop:10, fontSize:10, color:"#5a6478", paddingTop:8, borderTop:"1px solid #1c2435"}}><span style={{color:"#8a94a8", fontWeight:700}}>Standard:</span> {t.owasp_masvs}</div>)}
                            </div>
                          </div>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ── MANUAL TESTS PDF — focused report for customer self-test results.
//    Separate deliverable from the auto-scan PDF: cover, exec summary,
//    one detailed page per test (steps + customer evidence + severity),
//    methodology + references. Generated client-side via jsPDF.
// ─────────────────────────────────────────────────────────────────
function generateManualTestsReport({moduleKey, moduleLabel, tests, findings, date}) {
  const doc = new jsPDF({unit:"mm", format:"a4"});
  const pageW=210, margin=12, contentW=pageW-margin*2;
  const BLUE=[124,58,237], DARK=[15,23,42], GRAY=[100,116,139];
  const LIGHT=[248,250,252], WHITE=[255,255,255], LBLUE=[243,232,255];
  const RED=[220,38,38], ORANGE=[234,88,12], GREEN=[15,118,82], AMBER=[202,138,4];
  const SEV={HIGH:RED, MEDIUM:ORANGE, LOW:GREEN, "no-finding":GRAY, NOT_RUN:[148,163,184]};
  let y=0, _secN=0;
  // Strip emojis + map Unicode arrows/quotes to ASCII so jsPDF helvetica
  // doesn't render them as garbage bytes ("Ø=ßà", "!'", spaced-out chars).
  const _ascii = s => String(s == null ? "" : s)
      .replace(/[\u{1F000}-\u{1FFFF}]/gu, "")
      .replace(/[✓✔]/g, "v ")               // check / heavy check
      .replace(/[✘✖❌]/g, "X ")         // cross / heavy cross / X
      .replace(/[⚠]/g, "[!] ")                   // warning sign
      .replace(/[—–]/g, "-")                // em-dash / en-dash
      .replace(/[→]/g, "->")                     // right arrow
      .replace(/[←]/g, "<-")                     // left arrow
      .replace(/[‘’]/g, "'")                // curly single quotes
      .replace(/[“”]/g, '"')                // curly double quotes
      .replace(/[·]/g, "-")                      // middle dot
      .replace(/[︎️]/g, "");                // variation selectors VS-15/VS-16
  const fillR=(x,yy,w,h,c)=>{doc.setFillColor(...c);doc.rect(x,yy,w,h,"F");};
  const txt=(t,x,yy,sz,c,bold,align)=>{doc.setFont("Arial",bold?"bold":"normal");doc.setFontSize(sz||10);doc.setTextColor(...(c||DARK));doc.text(_ascii(t),x,yy,{align:align||"left"});};
  const chk=n=>{if(y+n>278){doc.addPage();y=18;drawHeader();}};
  const sHead=(t,yy)=>{_secN++;fillR(margin,yy,contentW,9,LBLUE);txt(_secN+". "+t,margin+4,yy+6.2,10,BLUE,true);return yy+13;};
  const drawHeader=()=>{txt(`VulnusLab — Manual Tests: ${moduleLabel}`,margin,10,7,GRAY);txt(date||"",pageW-margin,10,7,BLUE,false,"right");};

  // Aggregate
  const tally = {HIGH:0, MEDIUM:0, LOW:0, "no-finding":0, NOT_RUN:0};
  const enriched = tests.map(t => {
    const f = findings[t.id] || {};
    const status = f.status || "not_run";
    const sev = status === "done" ? (f.severity || "no-finding") : "NOT_RUN";
    tally[sev] = (tally[sev]||0) + 1;
    return {...t, customer: f, _sev: sev, _status: status};
  });
  const completed = enriched.length - tally.NOT_RUN;
  const _genId = (k,d)=>{const s=String(k)+"|"+String(d)+"|"+Date.now();let h=0;for(let i=0;i<s.length;i++)h=((h<<5)-h+s.charCodeAt(i))|0;return "VL-MT-"+Math.abs(h).toString(16).toUpperCase().padStart(8,"0").substring(0,8);};
  const REPORT_ID = _genId(moduleKey, date);

  // ── COVER ─────────────────────────────────────────────────────
  fillR(0,0,pageW,64,[0,0,0]);
  doc.setFont("helvetica","bold");doc.setFontSize(11);doc.setTextColor(...BLUE);
  doc.text("VULNUS",pageW/2-1,32,{align:"right"});doc.setTextColor(241,245,249);doc.text("LAB",pageW/2,32,{align:"left"});
  txt("MANUAL PENETRATION TEST REPORT",pageW/2,82,17,DARK,true,"center");
  txt(`Customer self-test results — ${moduleLabel}`,pageW/2,90,10,GRAY,false,"center");
  y=104;
  fillR(margin,y,contentW,8,DARK);txt("FIELD",margin+3,y+5.5,8,WHITE,true);txt("VALUE",margin+55,y+5.5,8,WHITE,true);y+=8;
  [["Module", moduleLabel],
   ["Module key", moduleKey],
   ["Date", date||""],
   ["Tests defined", String(tests.length)],
   ["Tests completed", `${completed} / ${tests.length}`],
   ["Report ID", REPORT_ID],
   ["Classification", "CONFIDENTIAL"]].forEach((row,i)=>{
    fillR(margin,y,contentW,8,i%2===0?LIGHT:WHITE);
    txt(row[0],margin+3,y+5.5,8.5,GRAY,true);
    if(row[0]==="Classification"){doc.setFillColor(...RED);doc.roundedRect(margin+55,y+2,28,4,1,1,"F");txt("CONFIDENTIAL",margin+57,y+5.2,7,WHITE,true);}
    else txt(row[1],margin+55,y+5.5,8.5,DARK);
    y+=8;
  });
  y+=8;

  // Trust banner
  fillR(margin,y,contentW,14,LBLUE);fillR(margin,y,3,14,BLUE);
  txt("[CUSTOMER ATTESTATION]",margin+8,y+6,8,BLUE,true);
  txt("Findings below are self-reported by the customer running each test locally on their own infrastructure.",margin+8,y+10,7.5,DARK);
  y+=20;

  // ── EXECUTIVE SUMMARY ────────────────────────────────────────
  y = sHead("Executive Summary", y);
  fillR(margin,y,contentW,8,DARK);["RESULT","COUNT","NOTE"].forEach((c,i)=>txt(c,margin+3+[0,55,90][i],y+5.5,8,WHITE,true));y+=8;
  const sumRows = [
    {s:"HIGH", v:tally.HIGH, note:"Critical — production-blocking issue confirmed"},
    {s:"MEDIUM", v:tally.MEDIUM, note:"Material risk — schedule fix in next release"},
    {s:"LOW", v:tally.LOW, note:"Hardening recommended"},
    {s:"no-finding", v:tally["no-finding"], note:"Customer confirmed: no issue found"},
    {s:"NOT_RUN", v:tally.NOT_RUN, note:"Test defined but not executed yet"},
  ];
  sumRows.forEach((row,i)=>{
    fillR(margin,y,contentW,7,i%2===0?LIGHT:WHITE);
    doc.setFillColor(...SEV[row.s]);doc.roundedRect(margin+3,y+1.5,40,4,1,1,"F");
    const lbl = row.s === "no-finding" ? "NO ISSUE" : row.s === "NOT_RUN" ? "NOT RUN" : row.s;
    txt(lbl,margin+4,y+5,7,WHITE,true);
    txt(String(row.v),margin+58,y+5,10,SEV[row.s],true);
    txt(row.note,margin+93,y+5,7.5,DARK);
    y+=7;
  });
  y+=6;

  // ── PROGRESS BAR ─────────────────────────────────────────────
  chk(20); y = sHead("Completion Progress", y);
  fillR(margin,y,contentW,16,LIGHT);
  doc.setFont("Arial","bold");doc.setFontSize(20);doc.setTextColor(...(completed===tests.length?GREEN:AMBER));
  doc.text(`${completed}/${tests.length}`, margin+8, y+11);
  txt(completed===tests.length ? "All defined manual tests executed" : `${tests.length-completed} test(s) still pending`, margin+40, y+8, 10, DARK, true);
  txt(`Report ID: ${REPORT_ID}`, margin+40, y+13, 7.5, GRAY);
  fillR(margin+40, y+15.5, contentW-44, 1.5, [226,232,240]);
  if(tests.length) fillR(margin+40, y+15.5, Math.max(((completed/tests.length)*(contentW-44)),1), 1.5, completed===tests.length?GREEN:AMBER);
  y += 22;

  // ── PER-TEST DETAILS ─────────────────────────────────────────
  const _completedTests = enriched.filter(t => t._status === "done");
  const _notRunTests = enriched.filter(t => t._status !== "done");
  _completedTests.forEach((t, idx) => {
    chk(40);
    y = sHead(t.title, y);
    txt(`Reference: ${t.ref || "—"}`, margin, y, 7.5, GRAY); y += 5;

    // Status badge
    const sc = SEV[t._sev] || GRAY;
    fillR(margin, y, contentW, 8, LIGHT); fillR(margin, y, 3, 8, sc);
    doc.setFillColor(...sc); doc.roundedRect(margin+5, y+1.5, 22, 5, 1, 1, "F");
    const lbl = t._sev === "no-finding" ? "NO ISSUE" : t._sev === "NOT_RUN" ? "NOT RUN" : t._sev;
    txt(lbl, margin+6, y+5.2, 7, WHITE, true);
    txt(`Tools: ${(t.tools_required||[]).join(", ").substring(0,90)}`, margin+32, y+5.2, 8, DARK);
    y += 11;

    // Customer prereqs
    chk(20); txt("WHAT CUSTOMER NEEDS", margin, y+4, 8, BLUE, true); y += 7;
    (t.customer_prereqs||[]).forEach(p => {
      chk(5);
      const lines = doc.splitTextToSize("• " + p, contentW - 4);
      lines.forEach(ln => { txt(ln, margin+2, y+3.5, 8, DARK); y += 4; });
    });
    y += 3;

    // Steps
    chk(20); txt("STEPS EXECUTED", margin, y+4, 8, BLUE, true); y += 7;
    (t.steps||[]).forEach((s, i) => {
      chk(6);
      const isCmd = String(s).startsWith("$");
      const text = isCmd ? String(s).slice(1).trim() : s;
      const lines = doc.splitTextToSize(`${i+1}. ${text}`, contentW - 4);
      lines.forEach(ln => {
        txt(ln, margin+2, y+3.5, 7.5, isCmd ? [22,163,74] : DARK);
        y += 4;
      });
    });
    y += 3;

    // What to look for
    chk(20); txt("WHAT TO LOOK FOR", margin, y+4, 8, BLUE, true); y += 7;
    const wlf = doc.splitTextToSize(t.what_to_look_for || "—", contentW - 4);
    wlf.forEach(ln => { chk(5); txt(ln, margin+2, y+3.5, 8, DARK); y += 4; });
    y += 4;

    // Customer findings (the actual point of this report)
    chk(20); txt("CUSTOMER FINDINGS", margin, y+4, 8, [220,38,38], true); y += 7;
    if (t._status !== "done") {
      fillR(margin, y, contentW, 8, [254,243,199]);
      txt("Test not yet executed by customer", margin+4, y+5.5, 8.5, AMBER, true);
      y += 11;
    } else {
      fillR(margin, y, contentW, 8, LIGHT);
      txt(`Severity assigned by customer: ${t._sev}`, margin+4, y+5.5, 8.5, sc, true);
      y += 10;
      const ev = _ascii(t.customer.evidence || "(no evidence text provided)");
      const evLines = doc.splitTextToSize(ev, contentW - 8);
      evLines.forEach(ln => { chk(5); txt(ln, margin+4, y+3.5, 7.5, DARK); y += 4; });
      y += 5;
    }

    // MASVS mapping
    if (t.owasp_masvs) {
      chk(8); fillR(margin, y, contentW, 6, [240,253,244]);
      txt(`Standard: ${t.owasp_masvs}`, margin+4, y+4, 7.5, GREEN, true);
      y += 9;
    }

    y += 4;
  });

  if (_notRunTests.length > 0) {
    chk(40); y = sHead("Tests Not Yet Executed (" + _notRunTests.length + ")", y);
    txt("The following tests are defined in the playbook but were not executed", margin, y, 8, GRAY); y += 4;
    txt("by the customer. Run them and re-export to include findings.", margin, y, 8, GRAY); y += 8;
    _notRunTests.forEach(t => {
      chk(6);
      fillR(margin, y, contentW, 5, LIGHT);
      txt(String(t.ref || ""), margin+3, y+3.5, 7.5, AMBER, true);
      txt(_ascii(t.title || ""), margin+22, y+3.5, 7.5, DARK);
      y += 5;
    });
    y += 6;
  }

  // ── APPENDIX ────────────────────────────────────────────────
  chk(30); y = sHead("Methodology + References", y);
  const MT_MODULE_DOCS = {
    recon_manual: {
      method: ["Manual tests complement the automated recon scanners by covering techniques","that require human creativity, judgment-based pivoting, or interactive analyst","tooling (OSINT mind-map walks, CDN-bypass to origin, IAM/OIDC trust mapping,","dark-web/leak-site monitoring, social-engineering pretext build).","Each test was executed locally by the customer using the steps documented","in this report. Evidence is self-reported and analyst-attested."],
      refs: ["PTES Intelligence Gathering - http://www.pentest-standard.org","NIST SP 800-115 - https://csrc.nist.gov/publications/detail/sp/800-115/final","MITRE PRE-ATT&CK (TA0043) - https://attack.mitre.org/tactics/TA0043/","OSINT Framework - https://osintframework.com","OWASP WSTG-INFO - https://owasp.org/www-project-web-security-testing-guide/"],
    },
    vuln_manual: {
      method: ["Manual tests complement the automated vulnerability scanners by covering","techniques that require human judgment or chained exploitation (business-logic","abuse, SAML golden-ticket, MFA bypass, container breakout, LLM model-extraction,","wireless/ICS recon). Each test was executed locally by the customer using the","steps documented in this report. Evidence is self-reported."],
      refs: ["OWASP Top 10 - https://owasp.org/Top10/","OWASP API Top 10 - https://owasp.org/API-Security/","CISA KEV - https://www.cisa.gov/known-exploited-vulnerabilities-catalog","FIRST EPSS - https://www.first.org/epss/","NIST SP 800-115 - https://csrc.nist.gov/publications/detail/sp/800-115/final","MITRE ATT&CK - https://attack.mitre.org/"],
    },
  };
  const _isMobile = String(moduleKey || "").startsWith("mobile");
  const _mtDocs = MT_MODULE_DOCS[moduleKey] || (_isMobile ? {
    method: ["Manual tests complement the automated scanners by covering techniques that","require a connected device, human creativity, or interactive tooling (Frida,","Burp, jailbroken iOS, rooted Android). Each test was executed locally by the","customer using the steps documented in this report. Evidence is self-reported."],
    refs: ["OWASP MASVS v2 - https://mas.owasp.org/MASVS/","OWASP MASTG - https://mas.owasp.org/MASTG/","Frida CodeShare - https://codeshare.frida.re","Objection - https://github.com/sensepost/objection","Apktool - https://apktool.org"],
  } : {
    method: ["Manual tests complement the automated scanners by covering techniques that","require human judgment, creativity, or interactive tooling.","Each test was executed locally by the customer using the steps documented","in this report. Evidence is self-reported."],
    refs: ["OWASP Testing Guide - https://owasp.org/www-project-web-security-testing-guide/","NIST SP 800-115 - https://csrc.nist.gov/publications/detail/sp/800-115/final","MITRE ATT&CK - https://attack.mitre.org/","PTES - http://www.pentest-standard.org"],
  });
  txt("A. Methodology", margin, y+5, 9, DARK, true); y += 8;
  _mtDocs.method.forEach(l => { chk(5); txt(l, margin+2, y+3.5, 7.5, GRAY); y += 4; });
  y += 4;
  txt("B. References", margin, y+5, 9, DARK, true); y += 8;
  _mtDocs.refs.forEach(l => { chk(5); txt(l, margin+2, y+3.5, 7.5, BLUE); y += 4.5; });
  y += 6;

  // End block
  if (y+30 > 284) { doc.addPage(); y=18; drawHeader(); }
  fillR(margin, y+5, contentW, 24, LBLUE); fillR(margin, y+5, 3, 24, BLUE);
  txt(`— END OF MANUAL TEST REPORT —`, pageW/2, y+13, 10, BLUE, true, "center");
  txt(`Report ID: ${REPORT_ID}`, pageW/2, y+18, 7.5, GRAY, false, "center");
  txt("vulnuslab.com · support@vulnuslab.com", pageW/2, y+25, 7, BLUE, true, "center");

  // Borders + footers on every page
  const total = doc.internal.getNumberOfPages();
  for (let i=1; i<=total; i++) {
    doc.setPage(i);
    doc.setDrawColor(...BLUE); doc.setLineWidth(1.2); doc.rect(0, 0, 210, 297, "S");
    if (i >= 2) {
      txt(`VulnusLab Manual Test Report — CONFIDENTIAL`, margin, 290, 6.5, GRAY);
      txt(`${REPORT_ID}`, pageW/2, 290, 6.5, GRAY, false, "center");
      txt("Page " + i + " of " + total, pageW-margin, 290, 6.5, BLUE, false, "right");
    }
  }

  const _safe = String(moduleKey || "module").replace(/[^a-zA-Z0-9_-]/g, "_");
  const _dt = (date || new Date().toISOString().substring(0,10)).replace(/[^0-9]/g,"").substring(0,8);
  doc.save(`manual_tests_${_safe}_${_dt}.pdf`);
}


