    const _apiHits = (r.api_endpoint_brute && r.api_endpoint_brute.hits) || [];
    if (_apiHits.length) _inv.push(["API endpoints discovered", `${_apiHits.length}: ${_apiHits.slice(0,5).map(h=>h.path).join(", ")}`]);

