// Saved Reports — lists the PDFs persisted by the report-upload hook and lets
// the user re-download or delete them. Reports are per-user (server enforces
// ownership via the JWT), so this only ever shows the current account's files.
function SavedReportsModule({ token }) {
  const [reports, setReports] = useState([]);
  const [loading, setLoading] = useState(false);
  const [busy, setBusy] = useState("");
  const [err, setErr] = useState("");

  const authTok = () => token || getAuthToken();

  const load = () => {
    setLoading(true); setErr("");
    const tok = authTok();
    fetch((getApiUrl() || "") + "/api/reports/list", { headers: tok ? { Authorization: "Bearer " + tok } : {} })
      .then((r) => (r.ok ? r.json() : Promise.reject("HTTP " + r.status)))
      .then((d) => setReports(Array.isArray(d.reports) ? d.reports : []))
      .catch((e) => setErr("Could not load saved reports (" + e + ")"))
      .finally(() => setLoading(false));
  };

  useEffect(() => { load(); /* eslint-disable-next-line */ }, []);

  const download = (rep) => {
    setBusy(rep.report_id);
    const tok = authTok();
    fetch((getApiUrl() || "") + "/api/reports/" + encodeURIComponent(rep.report_id), { headers: tok ? { Authorization: "Bearer " + tok } : {} })
      .then((r) => (r.ok ? r.blob() : Promise.reject("HTTP " + r.status)))
      .then((blob) => {
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url; a.download = rep.filename || (rep.report_id + ".pdf");
        document.body.appendChild(a); a.click(); a.remove();
        URL.revokeObjectURL(url);
      })
      .catch(() => window.alert("Download failed — the report may have been removed."))
      .finally(() => setBusy(""));
  };

  const remove = (rep) => {
    if (!window.confirm("Delete this saved report? This cannot be undone.")) return;
    setBusy(rep.report_id);
    const tok = authTok();
    fetch((getApiUrl() || "") + "/api/reports/" + encodeURIComponent(rep.report_id), { method: "DELETE", headers: tok ? { Authorization: "Bearer " + tok } : {} })
      .then(() => load())
      .catch(() => window.alert("Delete failed."))
      .finally(() => setBusy(""));
  };

  const fmtDate = (ts) => { try { return new Date((ts || 0) * 1000).toLocaleString(); } catch (e) { return "-"; } };
  const fmtSize = (b) => { b = b || 0; return b >= 1048576 ? (b / 1048576).toFixed(1) + " MB" : Math.max(1, Math.round(b / 1024)) + " KB"; };

  const cell = { padding: "10px 14px", fontSize: 13, color: "#c3ccda", borderBottom: "1px solid #1c2435", textAlign: "left", verticalAlign: "middle" };
  const th = { padding: "10px 14px", fontSize: 11, fontWeight: 800, color: "#5a6478", letterSpacing: 1, textTransform: "uppercase", textAlign: "left", borderBottom: "1px solid #1c2435" };
  const btn = (bg, bc, c) => ({ background: bg, border: "1px solid " + bc, color: c, fontSize: 12, fontWeight: 700, padding: "6px 12px", borderRadius: 8, cursor: "pointer" });

  return (
    <div style={{ padding: "28px 24px", maxWidth: 1100, margin: "0 auto" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 8 }}>
        <h1 style={{ fontSize: 26, fontWeight: 800, color: "#ffffff", margin: 0 }}>Saved Reports</h1>
        <button onClick={load} style={btn("rgba(59,158,255,0.12)", "rgba(59,158,255,0.4)", "#3b9eff")}>Refresh</button>
      </div>
      <p style={{ fontSize: 14, color: "#8a94a8", lineHeight: 1.6, marginTop: 0, marginBottom: 22 }}>
        Every PDF you generate is stored privately to your account, so you can re-download a deliverable even after closing the tab. Reports are isolated per user.
      </p>

      {err ? <div style={{ background: "rgba(224,35,71,0.1)", border: "1px solid rgba(224,35,71,0.4)", color: "#ff6b85", borderRadius: 10, padding: "12px 16px", fontSize: 13, marginBottom: 18 }}>{err}</div> : null}

      <div style={{ background: "#0d1320", border: "1px solid #1c2435", borderRadius: 12, overflow: "hidden" }}>
        {loading ? (
          <div style={{ padding: "40px 24px", textAlign: "center", color: "#8a94a8", fontSize: 14 }}>Loading...</div>
        ) : reports.length === 0 ? (
          <div style={{ padding: "48px 24px", textAlign: "center", color: "#8a94a8", fontSize: 14 }}>
            No saved reports yet. Run a scan and generate a PDF; it will appear here automatically.
          </div>
        ) : (
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr>
                <th style={th}>Module</th>
                <th style={th}>Target</th>
                <th style={th}>Generated</th>
                <th style={th}>Size</th>
                <th style={{ ...th, textAlign: "right" }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {reports.map((rep) => (
                <tr key={rep.report_id}>
                  <td style={{ ...cell, fontWeight: 700, color: "#ffffff", textTransform: "uppercase", fontSize: 12 }}>{(rep.module || "-").replace(/_/g, " ")}</td>
                  <td style={cell}>{rep.target || "-"}</td>
                  <td style={cell}>{fmtDate(rep.created_ts)}</td>
                  <td style={cell}>{fmtSize(rep.size)}</td>
                  <td style={{ ...cell, textAlign: "right", whiteSpace: "nowrap" }}>
                    <button disabled={busy === rep.report_id} onClick={() => download(rep)} style={{ ...btn("rgba(16,185,129,0.12)", "rgba(16,185,129,0.4)", "#10b981"), marginRight: 8, opacity: busy === rep.report_id ? 0.5 : 1 }}>Download</button>
                    <button disabled={busy === rep.report_id} onClick={() => remove(rep)} style={{ ...btn("rgba(224,35,71,0.1)", "rgba(224,35,71,0.35)", "#ff6b85"), opacity: busy === rep.report_id ? 0.5 : 1 }}>Delete</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

function ModuleAutoPanel({moduleKey, moduleLabel, emoji, color, playbook, token, apiUrl}) {
  const schema = MODULE_INPUT_SCHEMAS[moduleKey] || { ph: "Target", hint: "Target value" };
  const [target,    setTarget]    = useState("");
  const [authBearer,setAuthBearer]= useState("");   // optional: API key / JWT for some modules
  const [authCookie,setAuthCookie]= useState("");   // optional: session cookie (webapp / auth_attacks)
  const [showAuth,  setShowAuth]  = useState(false);
  // Scan-setup intake modal. The parent dispatches "vl-open-scan"
  // (detail = moduleKey) from its [active] effect whenever a module is
  // selected — that effect runs AFTER the panel is shown, so the modal
  // renders while the panel is visible (same reliable timing as the PDF
  // modal). Esc / click-outside / X all close it; "Configure & Scan"
  // reopens it.
  const [showScanModal, setShowScanModal] = useState(false);
  const [authConfirmed, setAuthConfirmed] = useState(false);
  const [scanDepth, setScanDepth] = useState("quick");
  useEffect(() => {
    const onOpen = (e) => { if (e && e.detail === moduleKey) { setShowScanModal(true); setAuthConfirmed(false); } };
    window.addEventListener("vl-open-scan", onOpen);
    return () => window.removeEventListener("vl-open-scan", onOpen);
  }, [moduleKey]);
  useEffect(() => {
    if (!showScanModal) return;
    const onKey = (e) => { if (e.key === "Escape") setShowScanModal(false); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [showScanModal]);
  // Advanced inputs (per-module — see MODULE_ADVANCED_INPUTS).
  // Persist between sessions so a Dockerfile / kubeconfig pasted once
  // survives reloads of the dashboard. kubeconfig is the sensitive one;
  // backend still tempfile + null-overwrite + unlink on every probe.
  const advancedFields = MODULE_ADVANCED_INPUTS[moduleKey] || [];
  const [advInputs, setAdvInputs] = useState(() => {
    const init = {image_ref:"", dockerfile_text:"", pod_spec_yaml:"", kubeconfig:"", repo_url:"", api_spec_url:""};
    try {
      const raw = localStorage.getItem(`vl_adv_inputs:${moduleKey}`);
      if (raw) Object.assign(init, JSON.parse(raw));
    } catch(_){}
    return init;
  });
  // VL-METHOD options — fields that go INSIDE options{} dict of scan request
  // (vs top-level like advInputs above). Per-module per MODULE_OPTIONS_INPUTS.
  const optionsFields = MODULE_OPTIONS_INPUTS[moduleKey] || [];
  const [optInputs, setOptInputs] = useState(() => {
    const init = {};
    optionsFields.forEach(k => {
      const def = OPTIONS_INPUT_DEFS[k];
      if (def && def.type === "checkbox") init[k] = def.default === true;
      else init[k] = "";
    });
    try {
      const raw = localStorage.getItem(`vl_opt_inputs:${moduleKey}`);
      if (raw) Object.assign(init, JSON.parse(raw));
    } catch(_){}
    return init;
  });
  const setOptField = (k, v) => {
    setOptInputs(p => {
      const next = {...p, [k]: v};
      try { localStorage.setItem(`vl_opt_inputs:${moduleKey}`, JSON.stringify(next)); } catch(_){}
      return next;
    });
  };
  // Container module: auto-open Advanced panel — image_ref / dockerfile /
  // pod-spec ARE the primary inputs for Container, not the Target field.
  // The Target field itself is hidden for this module (see render below),
  // so collapsing Advanced by default would leave the user with no inputs.
  const _containerMode = (moduleKey === "container_k8s");
  const [showAdv,   setShowAdv]   = useState(_containerMode);
  const setAdvField = (k, v) => {
    setAdvInputs(p => {
      const next = {...p, [k]: v};
      try { localStorage.setItem(`vl_adv_inputs:${moduleKey}`, JSON.stringify(next)); } catch(_){}
      return next;
    });
  };
  // vl-fill-inputs — a test-target chip attaches the target to THIS module's
  // actual inputs, in the form the module consumes: target (URL/host), advanced
  // (image_ref / repo_url / kubeconfig / dockerfile_text / pod_spec_yaml /
  // api_spec_url) and options{}. e.g. picking Juice Shop in Vuln fills both the
  // URL and image_ref so the web AND dependency/CVE tiers run, not just web.
  useEffect(() => {
    const onFill = (e) => {
      const d = (e && e.detail) || {};
      if (d.target !== undefined && d.target !== null) setTarget(d.target);
      if (d.adv) Object.entries(d.adv).forEach(([k, v]) => setAdvField(k, v));
      if (d.opts) Object.entries(d.opts).forEach(([k, v]) => setOptField(k, v));
    };
    window.addEventListener("vl-fill-inputs", onFill);
    return () => window.removeEventListener("vl-fill-inputs", onFill);
  });
  const advFilledCount = advancedFields.filter(k => (advInputs[k]||"").trim().length > 0).length;
  const [tiers,     setTiers]     = useState([]);
  const [running,   setRunning]   = useState(false);
  const [results,   setResults]   = useState({});
  const [progress,  setProgress]  = useState({done:0, total:0});
  // Phase E: chain_summary from /api/password/run_all_buffered or the
  // streaming wrapper's final NDJSON record. Populates the Attack Chain
  // section in the PDF generator. Stays null until a chain_summary
  // record arrives (password module only for now).
  const [chainSummary, setChainSummary] = useState(null);
  const [sevFilter, setSevFilter] = useState(null);
  const [expanded,  setExpanded]  = useState(null);
  const [searchTerm,setSearchTerm]= useState("");
  // VL-TIER (compact form per user feedback): collapsed dropdown button,
  // NOT a visible chip band. Opens a popover with per-tier checkboxes
  // when user clicks the "Tiers (N/M)" button.
  const [tierMenuOpen, setTierMenuOpen] = useState(false);
  const [selectedTiers, setSelectedTiers] = useState(null);   // null = all selected
  const [activeTab, setActiveTab] = useState("auto");
  const [manualState, setManualState] = useState({});
  const [manualExpanded, setManualExpanded] = useState({});  // {testId: true} → show steps/tools/prereqs
  const [manualSearch, setManualSearch] = useState("");
  const [manualFilter, setManualFilter] = useState("all"); // all | required | not_run | passed | failed
  const [history, setHistory] = useState([]);          // [{ts, target, results, sevCounts}, ...]
  const [showHistory, setShowHistory] = useState(false);

  // Load manual attestations + scan history from localStorage on mount
  useEffect(() => {
    const s = {};
    (MANUAL_TESTS_AUTO[moduleKey] || []).forEach(t => {
      try {
        const raw = localStorage.getItem(`vl_manual_auto:${moduleKey}:${t.id}`);
        if (raw) s[t.id] = JSON.parse(raw);
      } catch(_){}
    });
    setManualState(s);
    try {
      const raw = localStorage.getItem(`vl_scans:${moduleKey}`);
      if (raw) setHistory(JSON.parse(raw) || []);
    } catch(_){}
  }, [moduleKey]);

  const saveScanToHistory = (scanResults) => {
    const sevC = {CRITICAL:0,HIGH:0,MEDIUM:0,LOW:0,INFO:0,POSITIVE:0};
    Object.values(scanResults).forEach(r => {
      if (r.status === "done") sevC[(r.severity||"INFO").toUpperCase()] = (sevC[(r.severity||"INFO").toUpperCase()]||0) + 1;
    });
    const entry = {
      ts: new Date().toISOString(),
      target,
      results: scanResults,
      sevCounts: sevC,
      executed: Object.values(scanResults).filter(r => r.status === "done").length,
    };
    const next = [entry, ...history].slice(0, 5);    // keep last 5
    try {
      localStorage.setItem(`vl_scans:${moduleKey}`, JSON.stringify(next));
      setHistory(next);
    } catch(e) {
      // localStorage might be full — drop oldest first
      try { localStorage.setItem(`vl_scans:${moduleKey}`, JSON.stringify(next.slice(0,2))); setHistory(next.slice(0,2)); } catch(_) {}
    }
  };

  const loadFromHistory = (entry) => {
    setTarget(entry.target || "");
    setResults(entry.results || {});
    setProgress({done: entry.executed || 0, total: totalTools});
    setShowHistory(false);
    setSevFilter(null);
    setExpanded(null);
  };

  // ── Delta vs previous scan (same target) ──
  const prevScan = (() => {
    // For live current results: skip self (entry 0 = the just-saved scan)
    // For history-loaded view: also skip self
    return history.find(h => h.target === target && JSON.stringify(h.results) !== JSON.stringify(results));
  })();
  const sevRank = {CRITICAL:5,HIGH:4,MEDIUM:3,LOW:2,INFO:1,POSITIVE:0};
  const delta = (() => {
    if (!prevScan || Object.keys(results).length === 0) return null;
    let newFindings = 0, fixed = 0, persisted = 0, worsened = 0;
    const sevDelta = {CRITICAL:0, HIGH:0, MEDIUM:0, LOW:0};
    Object.entries(results).forEach(([tool, r]) => {
      if (r.status !== "done") return;
      const curSev = (r.severity || "INFO").toUpperCase();
      const prev = prevScan.results[tool];
      const prevSev = prev?.status === "done" ? (prev.severity || "INFO").toUpperCase() : null;
      if (!prevSev) {
        if (curSev !== "INFO" && curSev !== "POSITIVE") {
          newFindings++; if (sevDelta[curSev] !== undefined) sevDelta[curSev]++;
        }
      } else if (prevSev === curSev) {
        if (curSev !== "INFO" && curSev !== "POSITIVE") persisted++;
      } else if (sevRank[curSev] < sevRank[prevSev]) {
        if (prevSev !== "INFO" && prevSev !== "POSITIVE") fixed++;
      } else if (sevRank[curSev] > sevRank[prevSev]) {
        worsened++;
      }
    });
    return {newFindings, fixed, persisted, worsened, sevDelta, prevDate: prevScan.ts};
  })();

  // Per-tile delta marker
  const tileDelta = (tool) => {
    if (!prevScan || !results[tool] || results[tool].status !== "done") return null;
    const curSev = (results[tool].severity || "INFO").toUpperCase();
    const prev = prevScan.results[tool];
    const prevSev = prev?.status === "done" ? (prev.severity || "INFO").toUpperCase() : null;
    if (!prevSev) return curSev !== "INFO" && curSev !== "POSITIVE" ? "NEW" : null;
    if (prevSev === curSev) return null;
    if (sevRank[curSev] < sevRank[prevSev] && prevSev !== "POSITIVE") return "FIXED";
    if (sevRank[curSev] > sevRank[prevSev]) return "WORSE";
    return null;
  };

  const clearHistory = () => {
    if (!window.confirm("Clear all saved scans for this module?")) return;
    localStorage.removeItem(`vl_scans:${moduleKey}`);
    setHistory([]);
    setShowHistory(false);
  };

  const saveManual = (id, data) => {
    const next = {...manualState[id], ...data, updated_at: new Date().toISOString()};
    localStorage.setItem(`vl_manual_auto:${moduleKey}:${id}`, JSON.stringify(next));
    setManualState(p => ({...p, [id]: next}));
  };

  // tiersStatus: "loading" | "ready" | "failed"
  const [tiersStatus, setTiersStatus] = useState("loading");
  useEffect(() => {
    let cancelled = false;
    setTiersStatus("loading");
    const fetchTiers = async () => {
      const delays = [0, 400, 1200, 2500];  // 4 attempts total
      for (let i = 0; i < delays.length; i++) {
        if (cancelled) return;
        if (delays[i]) await new Promise(res => setTimeout(res, delays[i]));
        try {
          const ctrl = new AbortController();
          const timer = setTimeout(() => ctrl.abort(), 8000);
          const r = await fetch(`${apiUrl}/api/${moduleKey}/run_all/tiers`, {signal: ctrl.signal});
          clearTimeout(timer);
          if (!r.ok) continue;
          const d = await r.json();
          if (cancelled) return;
          if (Array.isArray(d.tiers) && d.tiers.length > 0) {
            setTiers(d.tiers);
            // VL-TIER: seed selected-tiers to "all" the first time tiers arrive
            setSelectedTiers(prev => prev || new Set(d.tiers.map(t => t.id)));
            setTiersStatus("ready");
            return;
          }
        } catch (_) { /* retry */ }
      }
      if (!cancelled) { setTiers([]); setTiersStatus("failed"); }
    };
    fetchTiers();
    return () => { cancelled = true; };
  }, [moduleKey, apiUrl]);

  const totalTools = tiers.reduce((s, t) => s + (t.count || 0), 0);

  // Run All gate: unlock when target is set OR any advanced input is set.
  // (Image-ref / dockerfile / pod-spec / repo-url probes don't need a network
  // target — the advanced input IS the target. We still send `target` in the
  // body so cluster/registry-context probes can use it; default to "n/a"
  // when only advanced inputs are provided so backend ScanRequest passes.)
  const hasAnyAdvInput = advancedFields.some(k => (advInputs[k] || "").trim().length > 0);
  // Container module: Target field is hidden, so canRun is gated on
  // having at least one advanced input set (image_ref is the primary).
  const canRun = (_containerMode
    ? (hasAnyAdvInput && !running)
    : ((target.trim().length > 0 || hasAnyAdvInput) && !running)) && authConfirmed;
  // The exact target sent to the scan, captured at run time so the PDF reports
  // what was ACTUALLY scanned even if the Target field changes before export.
  const scannedTargetRef = useRef("");
  const runAll = async () => {
    if (!canRun) return;
    const _q = await logConsent(target || advInputs.image_ref || advInputs.repo_url || "(advanced inputs)", moduleKey, token);   // authorization + quota gate
    if (_q && _q.quota_exceeded) { alert(_q.message || "Monthly scan limit reached. Upgrade to run more scans."); return; }
    setRunning(true);
    setResults({});
    setProgress({done:0, total: totalTools});

    // VL-TIER: only dispatch tools from tiers the user has selected.
    const _tiersToRun = selectedTiers
      ? tiers.filter(t => selectedTiers.has(t.id))
      : tiers;
    const all = [];
    _tiersToRun.forEach(t => (t.tools || []).forEach(tool => all.push({tool, tier:t.id})));
    const initial = {};
    all.forEach(x => { initial[x.tool] = {status:"queued", tier:x.tier, started:Date.now()}; });
    setResults(initial);

    try {
      // Build run_all body. Include optional auth_bearer / auth_cookie when set
      // so scanners that accept these (paid-API OSINT, webapp-auth scanners, etc.)
      // can use them. Webapp paths require /scan/ middle, others don't.
      // Container module: derive `target` from the primary advanced input
      // (image_ref preferred, then repo_url, then a synthetic label) so the
      // backend ScanRequest passes validation. The Target field is hidden
      // for Container — image_ref IS the scan subject.
      let _resolvedTarget = target.trim();
      if (_containerMode) {
        _resolvedTarget = (advInputs.image_ref || "").trim()
          || (advInputs.repo_url || "").trim()
          || "container-scan";
      }
      const runBody = {target: _resolvedTarget || "n/a", concurrency: 16};
      scannedTargetRef.current = _resolvedTarget || "";   // remember what we actually scanned
      if (authBearer.trim()) runBody.auth_bearer = authBearer.trim();
      if (authCookie.trim()) runBody.auth_cookie = authCookie.trim();
      // VL-TIER: pass tiers:[ids] when user has scoped scan to subset.
      // Omit field when ALL tiers selected so backend takes default path.
      if (selectedTiers && _tiersToRun.length < tiers.length) {
        runBody.tiers = _tiersToRun.map(t => t.id);
      }
      // Advanced per-module inputs (image_ref / dockerfile_text / pod_spec_yaml
      // / kubeconfig / repo_url / api_spec_url). Only attach what's set + what
      // the module declares it accepts — scanners ignore extras.
      advancedFields.forEach(k => {
        const v = (advInputs[k] || "").trim();
        if (v) runBody[k] = v;
      });
      // VL-METHOD options{} dict (Password module: userlist / passlist / hashes /
      // form_url / etc.). Attached as nested options{} so scanners read via
      // ctx.state.get('_options'). Empty string = not set; checkboxes always
      // passed as bool so always_deep / show_plaintext are explicit.
      if (optionsFields.length > 0) {
        const opts = {};
        optionsFields.forEach(k => {
          const def = OPTIONS_INPUT_DEFS[k] || {};
          const v = optInputs[k];
          if (def.type === "checkbox") {
            opts[k] = !!v;
          } else if (typeof v === "string" && v.trim().length > 0) {
            opts[k] = v.trim();
          }
        });
        if (Object.keys(opts).length > 0) runBody.options = opts;
      }
      // Universal scan-depth toggle: "deep" forces the deep stage on every scanner.
      if (scanDepth === "deep") runBody.options = {...(runBody.options || {}), always_deep: true};
      const runPath = (moduleKey === "webapp")
        ? `${apiUrl}/api/webapp/scan/run_all`
        : `${apiUrl}/api/${moduleKey}/run_all`;
      const r = await fetch(runPath, {
        method: "POST",
        headers: {"Content-Type":"application/json", "Authorization":`Bearer ${token}`},
        body: JSON.stringify(runBody),
      });
      const reader = r.body.getReader();
      const dec = new TextDecoder();
      let buf = "";
      let done = 0;
      while (true) {
        const {value, done:eof} = await reader.read();
        if (eof) break;
        buf += dec.decode(value, {stream:true});
        const lines = buf.split("\n");
        buf = lines.pop() || "";
        for (const line of lines) {
          if (!line.trim()) continue;
          try {
            const ev = JSON.parse(line);
            // Backend orchestrator (tools/_framework/orchestrator.py) emits
            // NDJSON events with `event:` field: scan_started, heartbeat,
            // tool_complete, scan_complete. Each tool_complete carries the
            // tool's data under `result`. (Legacy `type:result|error` schema
            // also accepted for any older orchestrator instances still alive.)
            const kind = ev.event || ev.type;
            const payload = ev.result || ev.data || {};
            if ((kind === "tool_complete" || kind === "result") && ev.tool) {
              const failed = payload._failed || payload.error;
              if (failed) {
                done++;
                setResults(p => ({...p, [ev.tool]: {
                  status: "error", tier: (initial[ev.tool]||{}).tier,
                  message: payload.error || payload._failed || "scanner failed",
                }}));
              } else {
                const f = payload.findings || [];
                const sev = payload.severity || "INFO";
                const start = (initial[ev.tool] || {}).started || Date.now();
                done++;
                setResults(p => ({...p, [ev.tool]: {
                  status: "done", tier: (initial[ev.tool]||{}).tier,
                  severity: sev, count: f.length, elapsed: Date.now() - start,
                  data: payload,
                }}));
              }
              setProgress({done, total: totalTools});
            } else if ((kind === "error") && ev.tool) {
              done++;
              setResults(p => ({...p, [ev.tool]: {status:"error", tier: (initial[ev.tool]||{}).tier, message: ev.message}}));
              setProgress({done, total: totalTools});
            } else if (kind === "chain_summary") {
              // Phase E: backend's streaming chain expansion emits this
              // as a final NDJSON record. Stash it so the PDF generator
              // can render the Attack Chain section.
              setChainSummary({
                chained_scans: ev.chained_scans || 0,
                chained_scanners: ev.chained_scanners || [],
                registered_chain_scanners: ev.registered_chain_scanners || [],
                error: ev.error || null,
              });
            }
            // scan_started / heartbeat / scan_complete: no UI update needed,
            // just keeps the stream alive past Cloudflare's 100s TTFB ceiling.
          } catch(_){}
        }
      }
    } catch(e) {
      console.error("run_all failed", e);
    } finally {
      setRunning(false);
      // Save scan to history (use a ref-style read of current results)
      setResults(currentResults => {
        if (Object.values(currentResults).some(r => r.status === "done")) {
          setTimeout(() => saveScanToHistory(currentResults), 100);
        }
        return currentResults;
      });
    }
  };

  const sevColor = (s) => ({
    CRITICAL:"#ff3e5e", HIGH:"#f97316", MEDIUM:"#eab308",
    LOW:"#3b9eff", INFO:"#5a6478", POSITIVE:"#00ff88"
  }[String(s||"").toUpperCase()] || "#5a6478");

  const dot = (r) => {
    if (!r) return "#5a6478";
    if (r.status === "queued") return "#5a6478";
    if (r.status === "error")  return "#7f1d1d";
    return sevColor(r.severity);
  };

  // ── VL-FLOW PDF export (universal across all 26 ModuleAutoPanel modules) ──
  const completedCount = Object.values(results).filter(r => r.status === "done").length;
  const [showPDFModal, setShowPDFModal] = useState(false);
  const runPDFExport = (cfg) => {
    // VL-FLOW PDF export delegates to the shared Recon-style template
    // (generateUniversalVLReport). pdfConfig is passed in from PDFConfigModal
    // (company, reporter, watermark, password, theme, etc.).
    // Container module hides the Target input — `target` field in state
    // is empty, so derive a meaningful display target from image_ref /
    // repo_url. Otherwise the PDF reads "Target: (none)" everywhere which
    // looks broken to an outside auditor.
    const _displayTarget = (() => {
      // Prefer the target actually scanned (captured at run time) over the live
      // Target field, which may have changed since the scan ran.
      const t = (scannedTargetRef.current || target || "").trim();
      if (t) return t;
      if (_containerMode) {
        return (advInputs.image_ref || "").trim()
          || (advInputs.repo_url || "").trim()
          || "(container artifacts)";
      }
      return "(none)";
    })();
    generateUniversalVLReport({
      target: _displayTarget,
      // Pass the user-supplied image_ref directly so the PDF generator
      // can prefer it over scanner-internal temp paths (Syft's
      // /tmp/stereoscope-XXX/oci-registry-image-YYY/sha256:...).
      userImageRef: (advInputs.image_ref || "").trim() || null,
      allResults: results,
      // Phase E: chain_summary from the streaming NDJSON wrapper. Drives
      // the Attack Chain section between Per-Tool and Risk Rating Matrix.
      chainSummary: chainSummary,
      date: (cfg && cfg.date) || new Date().toLocaleDateString("en-GB",{day:"2-digit",month:"long",year:"numeric"}),
      authenticated: !!(authBearer || authCookie),
      pdfConfig: cfg || {},
      moduleKey:      moduleKey,
      moduleLabel:    moduleLabel,
      moduleTitle:    moduleLabel.toUpperCase() + " REPORT",
      moduleSubtitle: moduleLabel + " Security Assessment",
      reportPrefix:   moduleKey.toUpperCase().replace(/[^A-Z0-9]/g, "").substring(0, 8),
      playbookPath:   playbook || (moduleKey + ".md"),
      methodology: [
        "Assessment uses the " + moduleLabel + " playbook.",
        "Scanners are organised across " + tiers.length + " tier(s) totalling " + totalTools + " technique(s).",
        "Every finding is independently triggered and re-confirmed by the VulnusLab engine."
      ],
      references: [
        "OWASP Top 10 (2021) - https://owasp.org/Top10/",
        "NIST SP 800-115 - https://csrc.nist.gov/publications/detail/sp/800-115/final",
        "CIS Critical Security Controls v8 - https://www.cisecurity.org/controls/v8",
        "MITRE ATT&CK - https://attack.mitre.org",
        "CWE - https://cwe.mitre.org"
      ]
    });
  };
  const generatePDF = () => setShowPDFModal(true);

  return (
    <div style={{padding:24, color:"#ffffff"}}>
      <div style={{display:"flex", alignItems:"center", gap:12, marginBottom:8}}>
        <span style={{fontSize:28}}>{emoji}</span>
        <h1 style={{fontSize:22, fontWeight:700}}>{moduleLabel}</h1>
        <ModuleTypeBadge moduleKey={moduleKey}/>
      </div>

      {/* Container module: the Target field + TestTargets chips are
          intentionally suppressed. Container scans are driven by the
          image_ref / dockerfile_text / pod_spec_yaml advanced inputs,
          NOT by a network hostname. Enterprise customers were getting
          confused (mixing DVWA image_ref with prod hostname Target).
          For Container, the Run button alone sits next to a banner
          pointing at the Advanced Inputs panel below. */}
      {/* Inline target / test-targets / container hint removed — every input
          now lives in the Scan Setup modal (opens on select / "Configure & Scan"). */}
      <div style={{display:"flex", gap:8, marginBottom:6}}>
        <button
          onClick={() => running ? null : setShowScanModal(true)} disabled={running}
          title={running ? "Scan in progress" : "Open scan setup (target, inputs, credentials) then start"}
          style={{background: running ? "#5a6478" : (color || "#3b9eff"),
                  border:"none", borderRadius:6, padding:"10px 18px",
                  color:"#fff", fontWeight:600, fontSize:13,
                  cursor: running ? "not-allowed" : "pointer"}}>
          {running ? `Running ${progress.done}/${progress.total}` : `Configure & Scan (${totalTools})`}
        </button>
        <button
          onClick={generatePDF}
          disabled={running || (completedCount === 0 && Object.keys(manualState).filter(k => manualState[k]?.status && manualState[k].status !== "NOT_RUN").length === 0)}
          title={
            completedCount === 0 && Object.keys(manualState).filter(k => manualState[k]?.status && manualState[k].status !== "NOT_RUN").length === 0
              ? "Run a scan or complete manual tests first"
              : `Download PDF (${completedCount} auto + ${Object.keys(manualState).filter(k => manualState[k]?.status && manualState[k].status !== "NOT_RUN").length} manual)`
          }
          style={{background: (running || (completedCount === 0 && Object.keys(manualState).filter(k => manualState[k]?.status && manualState[k].status !== "NOT_RUN").length === 0)) ? "#1c2435" : "#10b981",
                  border:"none", borderRadius:6, padding:"10px 14px",
                  color:"#fff", fontWeight:600, fontSize:13,
                  cursor: (running || (completedCount === 0 && Object.keys(manualState).filter(k => manualState[k]?.status && manualState[k].status !== "NOT_RUN").length === 0)) ? "not-allowed" : "pointer"}}>
          PDF
        </button>
      </div>

      {/* Example targets — clickable chips. Lets the customer try the module
          on a safe public test target without having to scan their own infra. */}
      {false && (MODULE_TARGET_EXAMPLES[moduleKey] || []).length > 0 && (
        <div style={{display:"flex", alignItems:"center", gap:6, marginBottom:8, flexWrap:"wrap"}}>
          <span style={{fontSize:10, color:"#5a6478", fontWeight:600, letterSpacing:0.5, textTransform:"uppercase"}}>Try:</span>
          {(MODULE_TARGET_EXAMPLES[moduleKey] || []).map((ex, idx) => (
            <button key={idx}
              onClick={() => setTarget(ex)}
              disabled={running}
              title={`Use ${ex} as the target (safe public test target)`}
              style={{background:"#0c1424", border:"1px solid #0e3a55", color:"#7fdcff",
                       borderRadius:12, padding:"3px 10px", fontSize:11,
                       fontFamily:"JetBrains Mono, monospace", cursor: running ? "not-allowed" : "pointer",
                       opacity: running ? 0.5 : 1}}>
              {ex}
            </button>
          ))}
        </div>
      )}

      {/* Per-module hint + auth/adv toggles removed — inputs live in Scan Setup modal */}
      {false && (
      <div style={{display:"flex", alignItems:"center", gap:14, marginBottom:14,
                    flexWrap:"wrap"}}>
        <span style={{fontSize:11, color:"#5a6478"}}>
          <span style={{color: schema.needsUpload ? "#f59e0b" : "#8a94a8"}}>
            {schema.needsUpload ? "📦 " : "💡 "}
          </span>
          {schema.hint}
        </span>
        <button onClick={() => setShowAuth(!showAuth)}
          style={{background:"transparent", border:"1px solid #1c2435",
                  borderRadius:4, padding:"3px 10px", color:"#8a94a8",
                  fontSize:10, cursor:"pointer", fontWeight:600,
                  textTransform:"uppercase", letterSpacing:1}}>
          {showAuth ? "▾" : "▸"} Auth headers {authBearer || authCookie ? "(set)" : "(optional)"}
        </button>
        {advancedFields.length > 0 && (
          <button onClick={() => setShowAdv(!showAdv)}
            style={{background:"transparent", border:"1px solid #1c2435",
                    borderRadius:4, padding:"3px 10px", color:"#8a94a8",
                    fontSize:10, cursor:"pointer", fontWeight:600,
                    textTransform:"uppercase", letterSpacing:1}}>
            {showAdv ? "▾" : "▸"} Advanced inputs {advFilledCount > 0 ? `(${advFilledCount}/${advancedFields.length} set)` : `(${advancedFields.length} optional)`}
          </button>
        )}
        {advFilledCount > 0 && !running && (
          <button
            onClick={() => {
              const cleared = {};
              advancedFields.forEach(k => { cleared[k] = ""; });
              setAdvInputs(prev => ({...prev, ...cleared}));
            }}
            title="Clear all advanced inputs (image_ref, Dockerfile, pod-spec, kubeconfig, repo_url)"
            style={{background:"transparent", border:"1px solid #7f1d1d",
                    borderRadius:4, padding:"3px 10px", color:"#ffa3b0",
                    fontSize:10, cursor:"pointer", fontWeight:600,
                    textTransform:"uppercase", letterSpacing:1}}>
            Clear ({advFilledCount})
          </button>
        )}
      </div>
      )}
      {/* MISMATCH banner (target vs image_ref) was removed once the
          Target field itself was hidden for Container — image_ref is
          now the sole canonical "what am I scanning" field, so there's
          nothing to mismatch against. For other modules the Target
          field is still primary, so cross-input mismatch is not a
          concept that applies. */}
      {false && (
        <div style={{display:"flex", gap:8, marginBottom:14, flexWrap:"wrap"}}>
          <div style={{flex:1, minWidth:280}}>
            <label style={{fontSize:10, color:"#5a6478", fontWeight:600,
                            textTransform:"uppercase", letterSpacing:1.2,
                            display:"block", marginBottom:3}}>
              Authorization: Bearer
            </label>
            <input type="text" placeholder="JWT / API key (paid OSINT, webapp auth, LLM, etc.)"
              value={authBearer} onChange={e => setAuthBearer(e.target.value)}
              disabled={running}
              style={{width:"100%", background:"#0d1320", border:"1px solid #1c2435",
                      borderRadius:5, padding:"7px 10px", color:"#c3ccda",
                      fontSize:11, fontFamily:"monospace", outline:"none"}}/>
          </div>
          <div style={{flex:1, minWidth:280}}>
            <label style={{fontSize:10, color:"#5a6478", fontWeight:600,
                            textTransform:"uppercase", letterSpacing:1.2,
                            display:"block", marginBottom:3}}>
              Cookie (session)
            </label>
            <input type="text" placeholder="session=abc123; csrf=xyz789  (webapp/auth_attacks)"
              value={authCookie} onChange={e => setAuthCookie(e.target.value)}
              disabled={running}
              style={{width:"100%", background:"#0d1320", border:"1px solid #1c2435",
                      borderRadius:5, padding:"7px 10px", color:"#c3ccda",
                      fontSize:11, fontFamily:"monospace", outline:"none"}}/>
          </div>
        </div>
      )}

      {/* Advanced per-module inputs — image_ref / dockerfile / pod-spec /
          kubeconfig / repo_url / api_spec_url. Backends accept these as
          optional fields on ScanRequest; scanners gracefully NOT_APPLICABLE
          when the input they need is missing, so users only need to fill
          the inputs relevant to the techniques they care about. */}
      {false && advancedFields.length > 0 && (
        <div style={{marginBottom:14, padding:"12px 14px", background:"#0b1220",
                      border:"1px solid #1c2435", borderRadius:6}}>
          <div style={{fontSize:10, color:"#5a6478", marginBottom:10,
                        textTransform:"uppercase", letterSpacing:1.2, fontWeight:700}}>
            Optional inputs — leave blank to skip the probes that need them
            {advancedFields.includes("kubeconfig") && (
              <span style={{color:"#f59e0b", marginLeft:8, textTransform:"none",
                              letterSpacing:0, fontSize:10, fontWeight:500}}>
                · kubeconfig is written to a 0600 tempfile, null-overwritten + deleted after every probe
              </span>
            )}
          </div>
          <div style={{display:"flex", flexDirection:"column", gap:12}}>
            {advancedFields.map(k => {
              const def = ADVANCED_INPUT_DEFS[k];
              if (!def) return null;
              const val = advInputs[k] || "";
              const presets = ADVANCED_INPUT_PRESETS[k] || [];
              return (
                <div key={k}>
                  <label style={{fontSize:10, color:"#8a94a8", fontWeight:600,
                                  textTransform:"uppercase", letterSpacing:1.2,
                                  display:"flex", justifyContent:"space-between",
                                  alignItems:"center", marginBottom:4}}>
                    <span>{def.label} <span style={{color:"#5a6478", fontWeight:400, textTransform:"none", letterSpacing:0}}>· {def.hint}</span></span>
                    {val && (
                      <button onClick={() => setAdvField(k, "")}
                        style={{background:"transparent", border:"1px solid #1c2435",
                                color:"#5a6478", borderRadius:3, padding:"1px 6px",
                                fontSize:9, cursor:"pointer", letterSpacing:1}}>
                        CLEAR
                      </button>
                    )}
                  </label>
                  {presets.length > 0 && (
                    <div style={{display:"flex", flexWrap:"wrap", gap:6, marginBottom:6}}>
                      {presets.map((p, i) => (
                        <button key={i} onClick={() => setAdvField(k, p.value)}
                          disabled={running} title={p.desc}
                          style={{background: val === p.value ? "#103a52" : "#0d1320",
                                  border: `1px solid ${val === p.value ? "#3b9eff" : "#1c2435"}`,
                                  borderRadius:4, padding:"3px 8px",
                                  color: val === p.value ? "#7fdcff" : "#8a94a8",
                                  fontSize:10, cursor: running ? "not-allowed" : "pointer",
                                  fontFamily:"JetBrains Mono, ui-monospace, monospace"}}>
                          {p.label}
                        </button>
                      ))}
                    </div>
                  )}
                  {def.type === "textarea" ? (
                    <textarea value={val} onChange={e => setAdvField(k, e.target.value)}
                      disabled={running} placeholder={def.ph} rows={def.rows || 6}
                      spellCheck={false}
                      style={{width:"100%", background:"#0d1320", border:"1px solid #1c2435",
                              borderRadius:5, padding:"8px 10px", color:"#c3ccda",
                              fontSize:11, fontFamily:"JetBrains Mono, ui-monospace, monospace",
                              outline:"none", resize:"vertical", lineHeight:1.5}}/>
                  ) : (
                    <input type="text" value={val} onChange={e => setAdvField(k, e.target.value)}
                      disabled={running} placeholder={def.ph}
                      style={{width:"100%", background:"#0d1320", border:"1px solid #1c2435",
                              borderRadius:5, padding:"7px 10px", color:"#c3ccda",
                              fontSize:11, fontFamily:"JetBrains Mono, ui-monospace, monospace",
                              outline:"none"}}/>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* VL-METHOD options panel — Password module only (for now).
          Renders userlist/passlist/hashes/form_url/etc. as input fields
          that get passed under the options{} dict of the scan request.
          Each scanner in the module reads only the fields it needs;
          irrelevant fields are ignored by scanners that don't use them. */}
      {false && optionsFields.length > 0 && (
        <div style={{marginBottom:14, padding:"12px 14px", background:"#0b1220",
                      border:"1px solid #103a52", borderRadius:6}}>
          <div style={{fontSize:10, color:"#00d4ff", marginBottom:10,
                        textTransform:"uppercase", letterSpacing:1.2, fontWeight:700}}>
            VL-METHOD inputs — what each scanner tries against the target
            <span style={{color:"#5a6478", marginLeft:8, textTransform:"none",
                            letterSpacing:0, fontSize:10, fontWeight:500}}>
              · paste wordlists / hashes / form details — scanner picks what it needs
            </span>
          </div>
          <div style={{display:"flex", flexDirection:"column", gap:12}}>
            {optionsFields.map(k => {
              const def = OPTIONS_INPUT_DEFS[k];
              if (!def) return null;
              const val = optInputs[k];
              const presets = OPTIONS_INPUT_PRESETS[k] || [];

              // Checkbox rendering (always_deep / show_plaintext)
              if (def.type === "checkbox") {
                return (
                  <div key={k} style={{display:"flex", alignItems:"center", gap:8}}>
                    <input type="checkbox" checked={!!val}
                      onChange={e => setOptField(k, e.target.checked)}
                      disabled={running}
                      style={{width:14, height:14, cursor:"pointer", accentColor:"#3b9eff"}}/>
                    <label style={{fontSize:11.5, color:"#c3ccda", fontWeight:500, cursor:"pointer"}}
                      onClick={() => !running && setOptField(k, !val)}>
                      {def.label}
                    </label>
                    {def.hint && (
                      <span style={{fontSize:10, color:"#5a6478", marginLeft:4}}>
                        — {def.hint}
                      </span>
                    )}
                  </div>
                );
              }

              // Text / textarea rendering
              return (
                <div key={k}>
                  <label style={{fontSize:10, color:"#8a94a8", fontWeight:600,
                                  textTransform:"uppercase", letterSpacing:1.2,
                                  display:"block", marginBottom:3}}>
                    {def.label}
                    {def.secret && (
                      <span style={{color:"#f59e0b", marginLeft:6, fontWeight:500,
                                      textTransform:"none", letterSpacing:0, fontSize:9}}>
                        [sensitive]
                      </span>
                    )}
                  </label>
                  {def.hint && (
                    <div style={{fontSize:10, color:"#5a6478", marginBottom:4}}>{def.hint}</div>
                  )}
                  {presets.length > 0 && (
                    <div style={{display:"flex", gap:6, flexWrap:"wrap", marginBottom:6}}>
                      {presets.map((p, i) => (
                        <button key={i} type="button" onClick={() => setOptField(k, p.value)}
                          disabled={running}
                          title={p.desc}
                          style={{background:"#1c2435", border:"1px solid #1c2435",
                                  borderRadius:4, padding:"3px 8px", color:"#8a94a8",
                                  fontSize:10, cursor:"pointer", fontWeight:500}}>
                          + {p.label}
                        </button>
                      ))}
                    </div>
                  )}
                  {def.type === "textarea" ? (
                    <textarea value={val || ""} onChange={e => setOptField(k, e.target.value)}
                      disabled={running} placeholder={def.ph} rows={def.rows || 5}
                      spellCheck={false}
                      style={{width:"100%", background:"#0d1320", border:"1px solid #1c2435",
                              borderRadius:5, padding:"8px 10px", color:"#c3ccda",
                              fontSize:11, fontFamily:"JetBrains Mono, ui-monospace, monospace",
                              outline:"none", resize:"vertical", lineHeight:1.5}}/>
                  ) : (
                    <input type="text" value={val || ""} onChange={e => setOptField(k, e.target.value)}
                      disabled={running} placeholder={def.ph}
                      style={{width:"100%", background:"#0d1320", border:"1px solid #1c2435",
                              borderRadius:5, padding:"7px 10px", color:"#c3ccda",
                              fontSize:11, fontFamily:"JetBrains Mono, ui-monospace, monospace",
                              outline:"none"}}/>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Recent Scans dropdown */}
      {history.length > 0 && (
        <div style={{marginBottom:12, position:"relative"}}>
          <button onClick={() => setShowHistory(!showHistory)}
            style={{background:"#1c2435", border:"1px solid #1c2435",
                    borderRadius:6, padding:"6px 12px", color:"#c3ccda",
                    fontSize:11, cursor:"pointer", display:"flex",
                    alignItems:"center", gap:8}}>
            <span></span>
            <span>Recent scans ({history.length})</span>
            <span style={{color:"#5a6478"}}>{showHistory ? "▼" : "▶"}</span>
          </button>
          {showHistory && (
            <div style={{position:"absolute", top:"100%", left:0, marginTop:4,
                          background:"#0d1320", border:"1px solid #1c2435",
                          borderRadius:6, minWidth:380, zIndex:100,
                          boxShadow:"0 4px 12px rgba(0,0,0,0.4)"}}>
              {history.map((entry, i) => {
                const date = new Date(entry.ts);
                const c = entry.sevCounts || {};
                return (
                  <div key={i} onClick={() => loadFromHistory(entry)}
                       style={{padding:"10px 12px", cursor:"pointer",
                                borderBottom: i < history.length-1 ? "1px solid #1c2435" : "none"}}
                       onMouseEnter={e => e.currentTarget.style.background = "#1c2435"}
                       onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
                    <div style={{display:"flex", justifyContent:"space-between",
                                  alignItems:"center", marginBottom:4}}>
                      <span style={{color:"#ffffff", fontSize:12, fontWeight:600}}>
                        {entry.target || "(no target)"}
                      </span>
                      <span style={{color:"#5a6478", fontSize:10}}>
                        {date.toLocaleString()}
                      </span>
                    </div>
                    <div style={{display:"flex", gap:8, fontSize:10}}>
                      <span style={{color:"#5a6478"}}>{entry.executed}/{totalTools} executed</span>
                      {c.CRITICAL > 0 && <span style={{color:sevColor("CRITICAL"), fontWeight:600}}>● {c.CRITICAL} CRITICAL</span>}
                      {c.HIGH > 0     && <span style={{color:sevColor("HIGH"),     fontWeight:600}}>● {c.HIGH} HIGH</span>}
                      {c.MEDIUM > 0   && <span style={{color:sevColor("MEDIUM"),   fontWeight:600}}>● {c.MEDIUM} MEDIUM</span>}
                      {c.LOW > 0      && <span style={{color:sevColor("LOW")}}>{c.LOW} LOW</span>}
                    </div>
                  </div>
                );
              })}
              <div onClick={clearHistory}
                   style={{padding:"6px 12px", cursor:"pointer", borderTop:"1px solid #1c2435",
                            color:"#ff3e5e", fontSize:10, textAlign:"center"}}>
                Clear history
              </div>
            </div>
          )}
        </div>
      )}

      {/* Auto / Manual tabs */}
      {(MANUAL_TESTS_AUTO[moduleKey] || []).length > 0 && (
        <div style={{display:"flex", gap:0, marginBottom:16, borderBottom:"1px solid #1c2435"}}>
          {[
            {id:"auto",   label:`AUTO SCAN · ${totalTools}`},
            {id:"manual", label:`MANUAL TESTS · ${(MANUAL_TESTS_AUTO[moduleKey] || []).length}`},
          ].map(t => (
            <button key={t.id} onClick={() => setActiveTab(t.id)}
              style={{background:"transparent", border:"none",
                      borderBottom: `2px solid ${activeTab === t.id ? (color || "#3b9eff") : "transparent"}`,
                      padding:"8px 16px", color: activeTab === t.id ? "#ffffff" : "#5a6478",
                      fontSize:11, fontWeight:700, cursor:"pointer",
                      textTransform:"uppercase", letterSpacing:1}}>
              {t.label}
            </button>
          ))}
        </div>
      )}

      {/* Delta banner — comparison to previous scan of same target */}
      {activeTab === "auto" && delta && (delta.newFindings + delta.fixed + delta.worsened) > 0 && (
        <div style={{display:"flex", alignItems:"center", gap:14, padding:"10px 14px",
                      marginBottom:12, background:"#0d1320", border:"1px solid #1c2435",
                      borderRadius:6}}>
          <span style={{fontSize:20}}></span>
          <div style={{flex:1, fontSize:11, color:"#c3ccda"}}>
            <div style={{marginBottom:2}}>
              <strong>Delta</strong> vs scan from {new Date(delta.prevDate).toLocaleDateString()}:
            </div>
            <div style={{display:"flex", gap:14, fontSize:11}}>
              {delta.fixed > 0 && (
                <span style={{color:"#00ff88", fontWeight:600}}>
                  {delta.fixed} FIXED
                </span>
              )}
              {delta.newFindings > 0 && (
                <span style={{color:"#ff3e5e", fontWeight:600}}>
                  ▲ {delta.newFindings} NEW
                </span>
              )}
              {delta.worsened > 0 && (
                <span style={{color:"#f97316", fontWeight:600}}>
                  ↗ {delta.worsened} WORSENED
                </span>
              )}
              {delta.persisted > 0 && (
                <span style={{color:"#8a94a8"}}>
                  {delta.persisted} persisting
                </span>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Severity filter chips + tool-name search (auto tab only) */}
      {activeTab === "auto" && tiers.length > 0 && completedCount > 0 && (
        <div style={{display:"flex", alignItems:"center", gap:6, marginBottom:12,
                     flexWrap:"wrap"}}>
          {["CRITICAL","HIGH","MEDIUM","LOW","INFO","POSITIVE"].map(s => {
            const n = Object.values(results).filter(r =>
              r.status === "done" && (r.severity||"INFO").toUpperCase() === s
            ).length;
            if (n === 0) return null;
            const active = sevFilter === s;
            return (
              <button key={s} onClick={() => setSevFilter(active ? null : s)}
                style={{background: active ? sevColor(s) : "#1c2435",
                        border: `1px solid ${active ? sevColor(s) : "#1c2435"}`,
                        borderRadius:4, padding:"4px 10px", color: active ? "#fff" : "#c3ccda",
                        fontSize:10, fontWeight:600, cursor:"pointer",
                        textTransform:"uppercase", letterSpacing:0.5}}>
                {s} ({n})
              </button>
            );
          })}
          {sevFilter && (
            <button onClick={() => setSevFilter(null)}
              style={{background:"transparent", border:"1px solid #1c2435",
                      borderRadius:4, padding:"4px 8px", color:"#8a94a8",
                      fontSize:10, cursor:"pointer"}}>
              clear ×
            </button>
          )}
          {/* VL-TIER: compact dropdown button. NOT a chip band.
              Single small pill -> popover with checkboxes when clicked. */}
          {tiers.length > 1 && selectedTiers && (
            <div style={{position:"relative", marginLeft:"auto"}}>
              <button onClick={() => setTierMenuOpen(o => !o)}
                style={{background: selectedTiers.size < tiers.length ? color : "#1c2435",
                        border:`1px solid ${selectedTiers.size < tiers.length ? color : "#1c2435"}`,
                        borderRadius:4, padding:"4px 10px",
                        color: selectedTiers.size < tiers.length ? "#fff" : "#c3ccda",
                        fontSize:10, fontWeight:600, cursor:"pointer",
                        textTransform:"uppercase", letterSpacing:0.5}}>
                Tiers {selectedTiers.size}/{tiers.length} {tierMenuOpen ? "▴" : "▾"}
              </button>
              {tierMenuOpen && (
                <div style={{position:"absolute", top:"calc(100% + 4px)", right:0, zIndex:50,
                              background:"#0d1320", border:"1px solid #1c2435",
                              borderRadius:6, padding:"8px 4px", minWidth:260,
                              maxHeight:300, overflowY:"auto",
                              boxShadow:"0 8px 24px rgba(0,0,0,0.4)"}}>
                  <div style={{display:"flex", justifyContent:"space-between",
                                padding:"4px 10px 8px", borderBottom:"1px solid #1c2435",
                                marginBottom:4}}>
                    <button onClick={() => setSelectedTiers(new Set(tiers.map(t=>t.id)))}
                      style={{background:"none", border:"none", color:"#8a94a8",
                              fontSize:10, cursor:"pointer", textDecoration:"underline"}}>
                      select all
                    </button>
                    <button onClick={() => setSelectedTiers(new Set())}
                      style={{background:"none", border:"none", color:"#8a94a8",
                              fontSize:10, cursor:"pointer", textDecoration:"underline"}}>
                      clear all
                    </button>
                  </div>
                  {tiers.map(t => {
                    const active = selectedTiers.has(t.id);
                    const m = t.id.match(/^tier(\d+)_(.+)$/);
                    const lbl = m ? `T${m[1]} · ${m[2].replace(/_/g," ")}` : t.id;
                    return (
                      <label key={t.id}
                        style={{display:"flex", alignItems:"center", gap:8,
                                padding:"5px 10px", cursor:"pointer", fontSize:11,
                                color:active ? "#ffffff" : "#8a94a8"}}
                        onMouseEnter={e => e.currentTarget.style.background = "#1c2435"}
                        onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
                        <input type="checkbox" checked={active}
                          onChange={() => {
                            setSelectedTiers(prev => {
                              const next = new Set(prev);
                              if (next.has(t.id)) next.delete(t.id); else next.add(t.id);
                              return next;
                            });
                          }}
                          style={{accentColor: color}}/>
                        <span style={{flex:1, textTransform:"capitalize"}}>{lbl}</span>
                        <span style={{color:"#5a6478", fontSize:10, fontFamily:"monospace"}}>
                          {t.count}
                        </span>
                      </label>
                    );
                  })}
                </div>
              )}
            </div>
          )}
          <input type="text" placeholder="search tool name..." value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
            style={{background:"#0d1320", border:"1px solid #1c2435",
                    borderRadius:4, padding:"4px 8px", color:"#c3ccda", fontSize:11,
                    width:180, outline:"none"}}/>
        </div>
      )}

      {activeTab === "auto" && (() => {
        // Premium list-style UI with colored section headers + full-width scanner rows
        const tierPalette = ["#8b5cf6","#06b6d4","#ff3e5e","#a855f7","#00ff88",
                              "#f59e0b","#ec4899","#3b9eff","#10b981","#f97316",
                              "#0ea5e9","#84cc16"];
        const sectionTitle = (tierId, idx) => {
          // tier1_port_service_enum → "SECTION 1 — PORT SERVICE ENUM"
          const m = tierId.match(/^tier(\d+)_(.+)$/);
          if (m) return `SECTION ${m[1]} — ${m[2].replace(/_/g," ").toUpperCase()}`;
          return `SECTION ${idx+1} — ${tierId.replace(/_/g," ").toUpperCase()}`;
        };
        const prettyName = (slug) => slug
          .replace(/_advisory$/,"").replace(/_probe$/,"").replace(/_audit$/,"")
          .replace(/_/g," ").replace(/\b\w/g, c => c.toUpperCase());
        const statusLabel = (r) => {
          if (!r || !r.status || r.status === "queued") return "QUEUED";
          if (r.status === "error") return "ERROR";
          if (r.severity && r.severity !== "INFO" && r.severity !== "POSITIVE") return r.severity;
          if (r.severity === "POSITIVE") return "PASS";
          return "DONE";
        };
        const statusColor = (r) => {
          if (!r || !r.status || r.status === "queued") return "#5a6478";
          if (r.status === "error") return "#ff3e5e";
          if (r.severity === "POSITIVE") return "#00ff88";
          return sevColor(r.severity);
        };
        return tiers.map((tier, idx) => {
          const filteredTools = (tier.tools || []).filter(tool => {
            const r = results[tool] || {};
            if (sevFilter && r.status === "done") {
              if ((r.severity||"INFO").toUpperCase() !== sevFilter) return false;
            }
            if (sevFilter && r.status !== "done") return false;
            if (searchTerm && !tool.toLowerCase().includes(searchTerm.toLowerCase())) return false;
            return true;
          });
          if (filteredTools.length === 0 && (sevFilter || searchTerm)) return null;
          const tcolor = tierPalette[idx % tierPalette.length];
          return (
            <div key={tier.id} style={{marginBottom:20}}>
              {/* Section header — colored left bar + label + subtitle */}
              <div style={{borderLeft:`3px solid ${tcolor}`,
                            paddingLeft:14, paddingBottom:8, marginBottom:0}}>
                <div style={{fontSize:11, fontWeight:700, color:tcolor,
                              textTransform:"uppercase", letterSpacing:1.5}}>
                  {sectionTitle(tier.id, idx)}
                </div>
                <div style={{fontSize:10, color:"#5a6478", marginTop:2}}>
                  {filteredTools.length === tier.count
                    ? `${tier.count} scanner${tier.count !== 1 ? "s" : ""}`
                    : `${filteredTools.length} of ${tier.count} scanner${tier.count !== 1 ? "s" : ""}`}
                </div>
              </div>
              {/* Full-width scanner rows */}
              {filteredTools.map((tool, ti) => {
                const r = results[tool] || {};
                const isExp = expanded === tool;
                const hasData = r.status === "done" && r.data?.findings?.length > 0;
                return (
                  <div key={tool}>
                    <div onClick={() => hasData && setExpanded(isExp ? null : tool)}
                         style={{display:"flex", alignItems:"center", gap:14,
                                  padding:"11px 14px", background:"#0d1320",
                                  borderTop: ti === 0 ? "1px solid #1c2435" : "1px solid #1c2435",
                                  borderBottom: ti === filteredTools.length - 1 ? "1px solid #1c2435" : "none",
                                  borderLeft: isExp ? `2px solid ${statusColor(r)}` : "2px solid transparent",
                                  cursor: hasData ? "pointer" : "default",
                                  transition:"border-left 0.15s"}}>
                      <span style={{width:9, height:9, borderRadius:"50%",
                                    background:dot(r), flexShrink:0}}></span>
                      <span style={{flex:1, color:"#ffffff", fontSize:13, fontWeight:500,
                                    overflow:"hidden", textOverflow:"ellipsis",
                                    whiteSpace:"nowrap"}}>{prettyName(tool)}</span>
                      {(() => {
                        const dm = tileDelta(tool);
                        if (!dm) return null;
                        const dmCol = dm === "FIXED" ? "#00ff88" : dm === "WORSE" ? "#f97316" : "#ff3e5e";
                        const dmSym = dm === "FIXED" ? "" : dm === "WORSE" ? "↗" : "▲";
                        return (
                          <span style={{padding:"2px 7px", borderRadius:3, fontSize:9,
                                        fontWeight:700, color:dmCol,
                                        border:`1px solid ${dmCol}`}}>
                            {dmSym} {dm}
                          </span>
                        );
                      })()}
                      {typeof r.count === "number" && r.count > 0 && (
                        <span style={{color:"#8a94a8", fontSize:11, fontWeight:600}}>
                          {r.count}
                        </span>
                      )}
                      {r.elapsed && (
                        <span style={{color:"#5a6478", fontSize:10, fontFamily:"monospace"}}>
                          {(r.elapsed/1000).toFixed(1)}s
                        </span>
                      )}
                      <span style={{color:statusColor(r), fontSize:10, fontWeight:700,
                                    textTransform:"uppercase", letterSpacing:1.2,
                                    minWidth:60, textAlign:"right"}}>
                        {statusLabel(r)}
                      </span>
                      {hasData && (
                        <span style={{color:"#5a6478", fontSize:10}}>
                          {isExp ? "▼" : "▶"}
                        </span>
                      )}
                    </div>
                    {isExp && hasData && (
                      <div style={{background:"#0a0e17",
                                    borderLeft:`2px solid ${statusColor(r)}`,
                                    padding:"12px 14px"}}>
                        {(r.data?.findings || []).map((f, i) => (
                          <div key={i} style={{marginBottom:10, paddingBottom:10,
                                                borderBottom: i < r.data.findings.length-1 ? "1px solid #1c2435" : "none"}}>
                            <div style={{display:"flex", alignItems:"center", gap:10, marginBottom:6}}>
                              <span style={{padding:"2px 8px", borderRadius:3, fontSize:10,
                                            fontWeight:700, background:sevColor(f.severity || r.severity),
                                            color:"#fff"}}>{f.severity || r.severity}</span>
                              {f.cvss && <span style={{color:"#8a94a8", fontSize:11}}>CVSS {f.cvss}</span>}
                              {f.cwe && f.cwe !== "N/A" && <span style={{color:"#8a94a8", fontSize:11}}>{f.cwe}</span>}
                              {f.confidence && <span style={{color:"#00ff88", fontSize:10, fontWeight:600}}>{f.confidence}</span>}
                            </div>
                            {f.detail && (
                              <div style={{color:"#ffffff", fontSize:12, marginBottom:6, lineHeight:1.5}}>
                                {f.detail}
                              </div>
                            )}
                            {f.evidence_marker && (
                              <div style={{color:"#8a94a8", fontSize:11, marginBottom:6,
                                            fontFamily:"monospace", background:"#0d1320",
                                            padding:"6px 10px", borderRadius:3, wordBreak:"break-word"}}>
                                {f.evidence_marker}
                              </div>
                            )}
                            {f.remediation && (
                              <div style={{color:"#7dffc0", fontSize:11, lineHeight:1.5}}>
                                {f.remediation}
                              </div>
                            )}
                          </div>
                        ))}
                        {r.data?.tests_summary && (
                          <div style={{color:"#5a6478", fontSize:10, marginTop:4, fontStyle:"italic"}}>
                            {r.data.tests_summary}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          );
        });
      })()}

      {activeTab === "auto" && !tiers.length && tiersStatus === "loading" && (
        <div style={{padding:"40px 20px", textAlign:"center"}}>
          <div style={{display:"inline-block", width:32, height:32, border:"3px solid #1c2435",
                        borderTop:`3px solid ${color}`, borderRadius:"50%",
                        animation:"spin 0.8s linear infinite", marginBottom:14}}/>
          <p style={{color:"#8a94a8", fontSize:13, margin:0}}>
            Loading technique catalogue<span className="dots">...</span>
          </p>
          <style>{`@keyframes spin { 0%{transform:rotate(0)} 100%{transform:rotate(360deg)} }`}</style>
        </div>
      )}
      {activeTab === "auto" && !tiers.length && tiersStatus === "failed" && (
        <div style={{padding:"30px 20px", background:"#1e1b2e", border:"1px solid #5b21b6",
                      borderRadius:6, marginTop:16}}>
          <div style={{color:"#ffa3b0", fontSize:14, fontWeight:600, marginBottom:8}}>
            Could not load technique catalogue
          </div>
          <div style={{color:"#8a94a8", fontSize:12, marginBottom:14, lineHeight:1.5}}>
            The backend at <code>GET /api/{moduleKey}/run_all/tiers</code> did not respond after
            4 retries. Possible causes: backend cold-starting, network blip, or
            <code> tools/{moduleKey}/</code> not registered. The most common fix is
            clicking Retry — it usually works the second time.
          </div>
          <button onClick={() => {
            setTiersStatus("loading");
            fetch(`${apiUrl}/api/${moduleKey}/run_all/tiers`)
              .then(r => r.ok ? r.json() : Promise.reject())
              .then(d => {
                if (Array.isArray(d.tiers) && d.tiers.length) {
                  setTiers(d.tiers); setTiersStatus("ready");
                } else { setTiersStatus("failed"); }
              })
              .catch(() => setTiersStatus("failed"));
          }} style={{padding:"7px 16px", background:color, color:"#fff",
                      border:"none", borderRadius:5, fontSize:12, fontWeight:600,
                      cursor:"pointer"}}>
            ⟲ Retry
          </button>
        </div>
      )}

      {/* Manual Tests tab */}
      {activeTab === "manual" && (() => {
        const allTests = MANUAL_TESTS_AUTO[moduleKey] || [];
        const DIFF_COLOR = {easy:"#00ff88", medium:"#f59e0b", hard:"#ff3e5e"};
        const matches = t => {
          if (manualSearch) {
            const q = manualSearch.toLowerCase();
            const hay = (t.title||"") + " " + (t.ref||"") + " " + (t.what_to_look_for||"") + " " + (t.tools_required||[]).join(",");
            if (!hay.toLowerCase().includes(q)) return false;
          }
          const st = (manualState[t.id]||{}).status;
          if (manualFilter === "required" && !t.required) return false;
          if (manualFilter === "not_run" && st && st !== "NOT_RUN") return false;
          if (manualFilter === "passed" && st !== "PASS") return false;
          if (manualFilter === "failed" && st !== "FAIL") return false;
          return true;
        };
        const filteredTests = allTests.filter(matches);
        const reqCount = allTests.filter(t => t.required).length;
        const doneCount = allTests.filter(t => {
          const s = (manualState[t.id]||{}).status; return s && s !== "NOT_RUN";
        }).length;
        return (
        <div>
          <div style={{background:"linear-gradient(135deg,#172554,#1e1b4b)", border:"1px solid #103a52", borderRadius:8, padding:"14px 16px", marginBottom:14}}>
            <div style={{display:"flex", justifyContent:"space-between", alignItems:"flex-start", gap:12, flexWrap:"wrap"}}>
              <div style={{minWidth:0, flex:1}}>
                <div style={{fontSize:13, fontWeight:700, color:"#fbbf24", marginBottom:4}}>
                  Analyst Manual Tests — {moduleLabel}
                </div>
                <div style={{fontSize:11, color:"#c3ccda", lineHeight:1.5}}>
                  {allTests.length} hands-on techniques from <code style={{color:"#a78bfa"}}>module_playbooks/{playbook}</code>.
                  Click <b>Details</b> for full steps + tools + prereqs. Mark <b>PASS</b>/<b>FAIL</b>/<b>N/A</b> with evidence, then Export PDF.
                </div>
              </div>
              <div style={{display:"flex", gap:14, fontSize:11, color:"#c3ccda", flexShrink:0}}>
                <div><b style={{color:"#fbbf24"}}>{reqCount}</b> required</div>
                <div><b style={{color:"#00ff88"}}>{doneCount}</b> / {allTests.length} done</div>
              </div>
            </div>
          </div>
          <div style={{display:"flex", gap:10, marginBottom:14, flexWrap:"wrap"}}>
            <input type="text" placeholder="Search tests, tools, refs..." value={manualSearch} onChange={e => setManualSearch(e.target.value)}
              style={{flex:1, minWidth:220, background:"#0d1320", border:"1px solid #1c2435", borderRadius:6, padding:"7px 10px", color:"#c3ccda", fontSize:12, outline:"none"}}/>
            {[
              {k:"all", label:`All (${allTests.length})`},
              {k:"required", label:`Required (${reqCount})`},
              {k:"not_run", label:"Not run"},
              {k:"passed", label:"Passed"},
              {k:"failed", label:"Failed"},
            ].map(f => (
              <button key={f.k} onClick={() => setManualFilter(f.k)}
                style={{background: manualFilter === f.k ? "#7c3aed" : "#1c2435", border:"1px solid #1c2435", borderRadius:6,
                        padding:"6px 12px", color:"#fff", fontSize:11, fontWeight:600, cursor:"pointer", whiteSpace:"nowrap"}}>
                {f.label}
              </button>
            ))}
          </div>
          <div style={{display:"grid", gridTemplateColumns:"repeat(auto-fill, minmax(460px, 1fr))", gap:12}}>
            {filteredTests.map(test => {
              const state = manualState[test.id] || {};
              const sev = state.severity || "INFO";
              const isOpen = !!manualExpanded[test.id];
              const diffC = DIFF_COLOR[test.difficulty] || "#5a6478";
              return (
                <div key={test.id} style={{background:"#0d1320", border:`1px solid ${state.status === "FAIL" ? sevColor(sev) : (state.status === "PASS" ? "#00ff88" : "#1c2435")}`,
                                             borderRadius:6, padding:14}}>
                  <div style={{display:"flex", justifyContent:"space-between", alignItems:"start", marginBottom:8, gap:8}}>
                    <div style={{flex:1, minWidth:0}}>
                      <div style={{display:"flex", gap:6, alignItems:"center", flexWrap:"wrap", marginBottom:4}}>
                        <span style={{color:"#8a94a8", fontSize:10, fontFamily:"monospace"}}>{test.ref}</span>
                        <span style={{background:diffC+"22", color:diffC, fontSize:9, fontWeight:700, padding:"1px 6px", borderRadius:3, textTransform:"uppercase"}}>{test.difficulty || "medium"}</span>
                        {test.time && <span style={{background:"#1c2435", color:"#8a94a8", fontSize:9, padding:"1px 6px", borderRadius:3}}>{test.time}</span>}
                        {test.cost && <span style={{background:test.cost === "paid" ? "#7c2d12" : "#0f3a1f", color:test.cost === "paid" ? "#fb923c" : "#00ff88", fontSize:9, fontWeight:700, padding:"1px 6px", borderRadius:3, textTransform:"uppercase"}}>{test.cost}</span>}
                        {test.required && <span style={{background:"#7c2d12", color:"#fbbf24", fontSize:9, fontWeight:700, padding:"1px 6px", borderRadius:3, border:"1px solid #fbbf24"}}>REQUIRED</span>}
                      </div>
                      <div style={{color:"#ffffff", fontSize:13, fontWeight:600, lineHeight:1.3}}>
                        {test.title}
                      </div>
                    </div>
                    <div style={{display:"flex", gap:4, flexShrink:0}}>
                      {["NOT_RUN","PASS","FAIL","NA"].map(s => (
                        <button key={s} onClick={() => saveManual(test.id, {status:s})}
                          style={{background: state.status === s
                                    ? (s === "PASS" ? "#00ff88" : s === "FAIL" ? "#ff3e5e" : s === "NA" ? "#5a6478" : "#1c2435")
                                    : "#1c2435",
                                  border:"1px solid #1c2435", borderRadius:3,
                                  padding:"2px 6px", color:"#fff", fontSize:9, fontWeight:700,
                                  cursor:"pointer"}}>
                          {s.replace("_"," ")}
                        </button>
                      ))}
                    </div>
                  </div>
                  <div style={{color:"#c3ccda", fontSize:11, marginBottom:8, lineHeight:1.5,
                                background:"#0a0e17", padding:"8px 10px", borderRadius:4, borderLeft:"3px solid #7c3aed"}}>
                    <div style={{fontSize:9, color:"#a78bfa", fontWeight:700, marginBottom:3, textTransform:"uppercase", letterSpacing:0.5}}>What to look for</div>
                    {test.what_to_look_for}
                  </div>
                  {(test.steps || test.tools_required || test.customer_prereqs) && (
                    <button onClick={() => setManualExpanded(p => ({...p, [test.id]: !p[test.id]}))}
                      style={{background:"none", border:"1px solid #1c2435", borderRadius:4, padding:"4px 10px", color:"#a78bfa", fontSize:10, fontWeight:600, cursor:"pointer", marginBottom:8}}>
                      {isOpen ? "▾ Hide details" : "▸ Details (tools, prereqs, steps)"}
                    </button>
                  )}
                  {isOpen && (
                    <div style={{background:"#0a0e17", border:"1px solid #1c2435", borderRadius:4, padding:"10px 12px", marginBottom:8, fontSize:11, lineHeight:1.55}}>
                      {test.tools_required && test.tools_required.length > 0 && (
                        <div style={{marginBottom:8}}>
                          <div style={{fontSize:9, color:"#00ff88", fontWeight:700, marginBottom:3, textTransform:"uppercase", letterSpacing:0.5}}>Tools required</div>
                          <div style={{color:"#c3ccda"}}>
                            {test.tools_required.map((t, i) => <span key={i} style={{display:"inline-block", background:"#0d1320", padding:"1px 7px", borderRadius:3, marginRight:5, marginBottom:3, color:"#00ff88", fontSize:10, fontFamily:"monospace"}}>{t}</span>)}
                          </div>
                        </div>
                      )}
                      {test.customer_prereqs && test.customer_prereqs.length > 0 && (
                        <div style={{marginBottom:8}}>
                          <div style={{fontSize:9, color:"#f59e0b", fontWeight:700, marginBottom:3, textTransform:"uppercase", letterSpacing:0.5}}>Customer prereqs</div>
                          <ul style={{margin:0, paddingLeft:18, color:"#c3ccda"}}>
                            {test.customer_prereqs.map((p, i) => <li key={i}>{p}</li>)}
                          </ul>
                        </div>
                      )}
                      {test.steps && test.steps.length > 0 && (
                        <div style={{marginBottom:8}}>
                          <div style={{fontSize:9, color:"#3b9eff", fontWeight:700, marginBottom:3, textTransform:"uppercase", letterSpacing:0.5}}>Steps</div>
                          <ol style={{margin:0, paddingLeft:18, color:"#c3ccda"}}>
                            {test.steps.map((s, i) => <li key={i} style={{marginBottom:3, fontFamily: s.startsWith("$") ? "monospace" : "inherit", fontSize: s.startsWith("$") ? 10 : 11}}>{s}</li>)}
                          </ol>
                        </div>
                      )}
                      {test.owasp_masvs && (
                        <div style={{borderTop:"1px solid #1c2435", paddingTop:6, marginTop:6, color:"#5a6478", fontSize:9, fontFamily:"monospace"}}>
                          <span style={{color:"#5a6478"}}>Standards:</span> {test.owasp_masvs}
                        </div>
                      )}
                    </div>
                  )}
                  {state.status === "FAIL" && (
                    <div style={{display:"flex", gap:8, marginBottom:8}}>
                      <select value={sev} onChange={e => saveManual(test.id, {severity:e.target.value})}
                        style={{background:"#0d1320", border:"1px solid #1c2435", borderRadius:3,
                                color:"#c3ccda", fontSize:10, padding:"3px 6px"}}>
                        {["CRITICAL","HIGH","MEDIUM","LOW","INFO"].map(s =>
                          <option key={s} value={s}>{s}</option>
                        )}
                      </select>
                    </div>
                  )}
                  {(state.status === "FAIL" || state.status === "PASS") && (
                    <textarea
                      placeholder="Evidence (commands, screenshots, output samples)..."
                      value={state.evidence || ""}
                      onChange={e => saveManual(test.id, {evidence:e.target.value})}
                      rows={3}
                      style={{width:"100%", background:"#0a0e17", border:"1px solid #1c2435",
                              borderRadius:3, padding:"6px 8px", color:"#c3ccda", fontSize:10,
                              fontFamily:"monospace", resize:"vertical", outline:"none"}}/>
                  )}
                  {state.updated_at && (
                    <div style={{color:"#5a6478", fontSize:9, marginTop:6}}>
                      saved {new Date(state.updated_at).toLocaleString()}
                    </div>
                  )}
                </div>
              );
            })}
            {filteredTests.length === 0 && (
              <div style={{gridColumn:"1 / -1", textAlign:"center", padding:"40px 20px", color:"#5a6478", fontSize:12}}>
                No tests match your search / filter.
              </div>
            )}
          </div>
        </div>
        );
      })()}
      <PDFConfigModal open={showPDFModal} onClose={() => setShowPDFModal(false)}
        moduleLabel={moduleLabel + " Report"}
        onGenerate={cfg => { try { runPDFExport(cfg); } catch(e){ alert("PDF error: "+(e.message||e)); } }}/>
      {/* ── SCAN SETUP MODAL ── per-module intake form: target + module inputs
          + credentials, opens on select, Esc / click-outside / X to close,
          Start Scan runs the same runAll pipeline. */}
      {showScanModal && (
        <div onClick={() => setShowScanModal(false)}
             style={{position:"fixed", inset:0, background:"rgba(0,0,0,0.85)", zIndex:9999,
                     display:"flex", alignItems:"center", justifyContent:"center", padding:20}}>
          <div onClick={e => e.stopPropagation()}
               style={{background:"#0d1320", border:`1px solid ${color || "#0e3a55"}`,
                       borderRadius:14, width:"100%", maxWidth:660, maxHeight:"90vh",
                       overflowY:"auto", padding:24, boxShadow:"0 20px 60px rgba(0,0,0,0.6)"}}>
            <div style={{display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:4}}>
              <div style={{fontSize:15, fontWeight:700, color:"#e6edf6"}}>{moduleLabel} — Scan Setup</div>
              <button onClick={() => setShowScanModal(false)} title="Close (Esc)"
                style={{background:"none", border:"1px solid #1c2435", borderRadius:6,
                        padding:"3px 11px", color:"#8a94a8", fontSize:16, fontWeight:700,
                        cursor:"pointer", lineHeight:1}}>×</button>
            </div>
            <div style={{fontSize:11, color:"#5a6478", marginBottom:18}}>
              Fill what you want to test, then Start Scan. Blank fields are skipped (their probes report "needs input"). Press Esc or click outside to close.
            </div>

            {_containerMode && (
              <div style={{marginBottom:16}}>
                <label style={{fontSize:10, color:"#8a94a8", fontWeight:700, textTransform:"uppercase", letterSpacing:1.2, display:"block", marginBottom:5}}>Test image / artifact</label>
                <TestChips moduleKey={moduleKey} setTarget={setTarget} running={running} />
              </div>
            )}

            {!_containerMode && (
              <div style={{marginBottom:16}}>
                <label style={{fontSize:10, color:"#8a94a8", fontWeight:700, textTransform:"uppercase", letterSpacing:1.2, display:"block", marginBottom:5}}>Target</label>
                <input type="text" placeholder={schema.ph} value={target}
                  onChange={e => setTarget(e.target.value)} disabled={running}
                  style={{width:"100%", background:"#0d1320", border:"1px solid #1c2435", borderRadius:6, padding:"10px 12px", color:"#fff", fontSize:13, outline:"none"}}/>
                <TestChips moduleKey={moduleKey} setTarget={setTarget} running={running} />
              </div>
            )}

            {optionsFields.length > 0 && (
              <div style={{marginBottom:16}}>
                <div style={{fontSize:10, color:"#00d4ff", marginBottom:4, textTransform:"uppercase", letterSpacing:1.2, fontWeight:700}}>Module inputs — what each scanner tries against the target</div>
                {(MODULE_REQUIRED_INPUTS[moduleKey] || []).length > 0 && (
                  <div style={{fontSize:10, color:"#ffb454", marginBottom:10}}>Required for a meaningful scan: {(MODULE_REQUIRED_INPUTS[moduleKey] || []).map(k => (OPTIONS_INPUT_DEFS[k] || {}).label || k).join(", ")}</div>
                )}
                <div style={{display:"flex", flexDirection:"column", gap:12}}>
                  {optionsFields.map(k => {
                    const def = OPTIONS_INPUT_DEFS[k];
                    if (!def) return null;
                    const val = optInputs[k];
                    const presets = OPTIONS_INPUT_PRESETS[k] || [];
                    if (def.type === "checkbox") {
                      return (
                        <div key={k} style={{display:"flex", alignItems:"center", gap:8}}>
                          <input type="checkbox" checked={!!val} onChange={e => setOptField(k, e.target.checked)} disabled={running}
                            style={{width:14, height:14, cursor:"pointer", accentColor:"#3b9eff"}}/>
                          <label style={{fontSize:11.5, color:"#c3ccda", fontWeight:500, cursor:"pointer"}} onClick={() => !running && setOptField(k, !val)}>{def.label}</label>
                          {def.hint && (<span style={{fontSize:10, color:"#5a6478", marginLeft:4}}>— {def.hint}</span>)}
                        </div>
                      );
                    }
                    return (
                      <div key={k}>
                        <label style={{fontSize:10, color:"#8a94a8", fontWeight:600, textTransform:"uppercase", letterSpacing:1.2, display:"block", marginBottom:3}}>
                          {def.label}{def.secret && (<span style={{color:"#f59e0b", marginLeft:6, fontWeight:500, textTransform:"none", letterSpacing:0, fontSize:9}}>[sensitive]</span>)}
                        </label>
                        {def.hint && (<div style={{fontSize:10, color:"#5a6478", marginBottom:4}}>{def.hint}</div>)}
                        {presets.length > 0 && (
                          <div style={{display:"flex", gap:6, flexWrap:"wrap", marginBottom:6}}>
                            {presets.map((p, i) => (
                              <button key={i} type="button" onClick={() => setOptField(k, p.value)} disabled={running} title={p.desc}
                                style={{background:"#1c2435", border:"1px solid #1c2435", borderRadius:4, padding:"3px 8px", color:"#8a94a8", fontSize:10, cursor:"pointer", fontWeight:500}}>+ {p.label}</button>
                            ))}
                          </div>
                        )}
                        {def.type === "textarea" ? (
                          <textarea value={val || ""} onChange={e => setOptField(k, e.target.value)} disabled={running} placeholder={def.ph} rows={def.rows || 5} spellCheck={false}
                            style={{width:"100%", background:"#0d1320", border:"1px solid #1c2435", borderRadius:5, padding:"8px 10px", color:"#c3ccda", fontSize:11, fontFamily:"JetBrains Mono, ui-monospace, monospace", outline:"none", resize:"vertical", lineHeight:1.5}}/>
                        ) : (
                          <input type="text" value={val || ""} onChange={e => setOptField(k, e.target.value)} disabled={running} placeholder={def.ph}
                            style={{width:"100%", background:"#0d1320", border:"1px solid #1c2435", borderRadius:5, padding:"7px 10px", color:"#c3ccda", fontSize:11, fontFamily:"JetBrains Mono, ui-monospace, monospace", outline:"none"}}/>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            )}

            {advancedFields.length > 0 && (
              <div style={{marginBottom:16}}>
                <div style={{fontSize:10, color:"#5a6478", marginBottom:10, textTransform:"uppercase", letterSpacing:1.2, fontWeight:700}}>Advanced inputs — leave blank to skip those probes</div>
                <div style={{display:"flex", flexDirection:"column", gap:12}}>
                  {advancedFields.map(k => {
                    const def = ADVANCED_INPUT_DEFS[k];
                    if (!def) return null;
                    const val = advInputs[k] || "";
                    const presets = ADVANCED_INPUT_PRESETS[k] || [];
                    return (
                      <div key={k}>
                        <label style={{fontSize:10, color:"#8a94a8", fontWeight:600, textTransform:"uppercase", letterSpacing:1.2, display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:4}}>
                          <span>{def.label} <span style={{color:"#5a6478", fontWeight:400, textTransform:"none", letterSpacing:0}}>· {def.hint}</span></span>
                          {val && (<button onClick={() => setAdvField(k, "")} style={{background:"transparent", border:"1px solid #1c2435", color:"#5a6478", borderRadius:3, padding:"1px 6px", fontSize:9, cursor:"pointer", letterSpacing:1}}>CLEAR</button>)}
                        </label>
                        {presets.length > 0 && (
                          <div style={{display:"flex", flexWrap:"wrap", gap:6, marginBottom:6}}>
                            {presets.map((p, i) => (
                              <button key={i} onClick={() => setAdvField(k, p.value)} disabled={running} title={p.desc}
                                style={{background: val === p.value ? "#103a52" : "#0d1320", border: `1px solid ${val === p.value ? "#3b9eff" : "#1c2435"}`, borderRadius:4, padding:"3px 8px", color: val === p.value ? "#7fdcff" : "#8a94a8", fontSize:10, cursor: running ? "not-allowed" : "pointer", fontFamily:"JetBrains Mono, ui-monospace, monospace"}}>{p.label}</button>
                            ))}
                          </div>
                        )}
                        {def.type === "textarea" ? (
                          <textarea value={val} onChange={e => setAdvField(k, e.target.value)} disabled={running} placeholder={def.ph} rows={def.rows || 6} spellCheck={false}
                            style={{width:"100%", background:"#0d1320", border:"1px solid #1c2435", borderRadius:5, padding:"8px 10px", color:"#c3ccda", fontSize:11, fontFamily:"JetBrains Mono, ui-monospace, monospace", outline:"none", resize:"vertical", lineHeight:1.5}}/>
                        ) : (
                          <input type="text" value={val} onChange={e => setAdvField(k, e.target.value)} disabled={running} placeholder={def.ph}
                            style={{width:"100%", background:"#0d1320", border:"1px solid #1c2435", borderRadius:5, padding:"7px 10px", color:"#c3ccda", fontSize:11, fontFamily:"JetBrains Mono, ui-monospace, monospace", outline:"none"}}/>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            )}

            <AuthPanel target={target} token={token} authCookie={authCookie} setAuthCookie={setAuthCookie} authBearer={authBearer} setAuthBearer={setAuthBearer} defaultOpen={true} />

            <div style={{borderTop:"1px solid #1c2435", paddingTop:14, marginTop:4}}>
              <div style={{display:"flex", alignItems:"center", gap:8, marginBottom:12, flexWrap:"wrap"}}>
                <span style={{fontSize:10, color:"#8a94a8", fontWeight:700, textTransform:"uppercase", letterSpacing:1.2}}>Scan depth:</span>
                {["quick","deep"].map(d => (
                  <button key={d} onClick={() => setScanDepth(d)} disabled={running}
                    style={{background: scanDepth===d ? (color||"#3b9eff") : "#0d1320", border:`1px solid ${scanDepth===d ? (color||"#3b9eff") : "#1c2435"}`, borderRadius:5, padding:"4px 12px", color: scanDepth===d ? "#fff" : "#8a94a8", fontSize:11, fontWeight:600, cursor:"pointer"}}>
                    {d==="quick" ? "Quick (gated)" : "Deep (force deep stage)"}
                  </button>
                ))}
              </div>
              <label style={{display:"flex",alignItems:"flex-start",gap:8,margin:"4px 0 14px",padding:"10px 12px",background:"#0a0e17",border:`1px solid ${authConfirmed?"#1f6f3f":"#3a2a12"}`,borderRadius:8,cursor:"pointer",fontSize:12,color:"#b8c2d4",lineHeight:1.45}}>
                <input type="checkbox" checked={authConfirmed} onChange={e=>setAuthConfirmed(e.target.checked)} style={{marginTop:2,accentColor:"#3b9eff",cursor:"pointer"}}/>
                <span>I confirm I am <b>authorized</b> to scan this target (I own it or have written permission). VulnusLab records this authorization. Unauthorized scanning is illegal.</span>
              </label>
              <div style={{display:"flex", gap:10, justifyContent:"flex-end"}}>
                <button onClick={() => setShowScanModal(false)}
                  style={{background:"transparent", border:"1px solid #1c2435", borderRadius:6, padding:"9px 16px", color:"#8a94a8", fontWeight:600, fontSize:13, cursor:"pointer"}}>Close</button>
                <button onClick={() => { setShowScanModal(false); runAll(); }} disabled={!canRun}
                  title={!canRun ? (_containerMode ? "Fill at least one input (image_ref / Dockerfile / pod YAML / repo URL)" : "Enter a target OR fill at least one input") : ""}
                  style={{background: canRun ? (color || "#3b9eff") : "#1c2435", border:"none", borderRadius:6, padding:"9px 20px", color:"#fff", fontWeight:700, fontSize:13, cursor: canRun ? "pointer" : "not-allowed"}}>
                  {running ? "Scanning..." : `Start Scan (${totalTools})`}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

